-- 4. ENSURE LAW PROVISIONS EXIST
INSERT INTO law_provisions (id, law_id, section_number, title, simple_summary, full_text, penalty_or_remedy) VALUES
(8, 9, 'Section 6 & 7', 'Request for Obtaining Information & Disposal of Request', 'Citizens can submit written or online RTI requests; Public Information Officer must provide information within 30 days or 48 hours for life and liberty.', 'A person, who desires to obtain any information under this Act, shall make a request in writing...', 'Rs. 250 per day up to Rs. 25,000 penalty on PIO for unjustified refusal or delay.'),
(9, 10, 'Section 19 & 21', 'Reporting of Offences and Punishment for Failure to Report', 'Mandatory duty on any person having knowledge of child abuse to report immediately to Special Juvenile Police Unit or local police.', 'Notwithstanding anything contained in the Code of Criminal Procedure...', 'Imprisonment up to 6 months or fine for deliberate failure to report.'),
(10, 11, 'Section 154 & 157', 'Information in Cognizable Cases & Procedure for Investigation', 'Police must register an FIR for cognizable offences immediately without jurisdictional excuses (Zero FIR doctrine).', 'Every information relating to the commission of a cognizable offence...', 'Disciplinary action and criminal prosecution under Section 166A IPC for refusing FIR.'),
(11, 12, 'Section 12 & 13', 'Right to Grievance Redressal and Erasure of Personal Data', 'Data Principals have statutory rights to obtain summary of personal data, correct inaccuracies, and seek complete erasure.', 'A Data Principal shall have the right to obtain from the Data Fiduciary confirmation...', 'Data Protection Board inquiry and substantial civil penalties on non-compliant Data Fiduciaries.'),
(12, 13, 'Section 18', 'Return of Amount and Compensation for Delay', 'Homebuyer is entitled to full refund with prescribed interest or monthly interest for delayed possession of flat/plot.', 'If the promoter fails to complete or is unable to give possession of an apartment...', 'Refund of entire principal amount with SBI Highest MCLR + 2% interest rate.'),
(13, 14, 'Section 12 & 18', 'Application to Magistrate and Protection Orders', 'Aggrieved woman can file petition directly to Magistrate for urgent protection orders, residence rights, and interim monetary relief.', 'An aggrieved person or a Protection Officer on behalf of the aggrieved person may present an application...', 'Magistrate order restraining respondent from domestic violence or entering shared household.'),
(14, 15, 'Section 5 & 12', 'Right to Payment of Maternity Benefit and Dismissal Protection', 'Women employees are entitled to 26 weeks paid maternity leave; employer cannot dismiss a woman during maternity absence.', 'Every woman shall be entitled to, and her employer shall be liable for, the payment of maternity benefit...', 'Imprisonment up to one year and mandatory payment of full wages.'),
(15, 16, 'Section 4 & 7', 'Payment of Gratuity and Determination of Amount', 'Gratuity is payable on termination of employment after 5 years of continuous service calculated at 15 days wages per year.', 'Gratuity shall be payable to an employee on the termination of his employment...', 'Recovery certificate issued to District Collector with 10% compound interest.')
ON CONFLICT (id) DO NOTHING;

-- 5. SEED ALL 70 VERIFIED LEGAL RIGHTS (5 PER CATEGORY FOR ALL 14 CATEGORIES)
INSERT INTO rights (
    id, category_id, title, slug, short_description, simple_explanation, detailed_explanation,
    who_it_applies_to, why_it_applies, real_world_example, recommended_actions, required_documents,
    relevant_authority, relevant_service, procedure_summary, official_source_url, source_authority,
    last_verified, effective_from, version, verification_status, content_status, view_count
) VALUES
(101, 1, 'Protection Against Sexual Harassment at Workplace (POSH)', 'posh-act-workplace-protection', 'Every woman employee has the legal right to a safe work environment free from sexual harassment under the POSH Act, 2013.', 'If anyone at your workplace makes unwelcome physical contact, demands sexual favors, makes sexually colored remarks, or creates a hostile environment, you can file a complaint with your company ICC.', 'Under the POSH Act 2013, all establishments with 10+ employees must constitute an Internal Complaints Committee. Complainants are entitled to up to 3 months paid leave during inquiry.', 'All women workers, permanent, contractual, intern, probationer, in private and public sectors.', 'Protects bodily autonomy, dignity, and gender equality under Articles 14, 19, and 21.', 'Ananya faced discriminatory threats from her lead after refusing advances. The ICC recommended disciplinary action and granted paid leave during the inquiry.', '1. Document dates, times, screenshots, emails, and witness names.
2. Submit formal written complaint to ICC within 3 months.
3. Request interim measures like transfer or leave if needed.
4. If company lacks ICC, approach the District Local Complaints Committee (LCC).', 'Written complaint copy, Email transcripts, Chat screenshots, Performance appraisal records, Witness statements.', 'Internal Complaints Committee (ICC) / LCC', 'She-Box Online Portal', '1. File complaint within 3 months. 2. ICC issues notice. 3. Inquiry completed in 90 days. 4. Employer implements recommendations in 60 days.', 'https://www.indiacode.nic.in/handle/123456789/2104', 'Ministry of Women and Child Development, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(102, 1, 'Right to 26 Weeks Paid Maternity Leave & Job Security', 'maternity-benefit-act-rights', 'Female employees are entitled to 26 weeks of fully paid maternity leave and protection against wrongful termination.', 'If you have worked for at least 80 days with an employer in the past 12 months, you are entitled to 26 weeks of paid maternity leave. Your employer cannot fire you because of pregnancy.', 'Section 5 & 12 of the Maternity Benefit Act, 1961 mandates 26 weeks paid leave for up to two children and prohibits discharge or dismissal during maternity absence.', 'Employed women across private companies, factories, mines, plantations, and commercial establishments.', 'Ensures maternal and child health and career continuity.', 'Meenakshi was asked to resign after announcing pregnancy. A legal notice citing Section 12 resulted in full maternity benefits and job retention.', '1. Give written notice specifying expected delivery date.
2. Submit medical certificate from registered doctor.
3. Claim maternity benefit 8 weeks before delivery.
4. If denied, lodge complaint with State Labour Commissioner.', 'Employment contract, Doctor pregnancy certificate, Written notice to employer, Salary slips.', 'Office of the Labour Commissioner / Labour Court', 'State Labour Dispute Redressal Portal', '1. Serve notice. 2. Employer disburses benefit. 3. If withheld, file Section 17 claim. 4. Inspector directs immediate recovery.', 'https://www.indiacode.nic.in/handle/123456789/1681', 'Ministry of Labour and Employment, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(103, 1, 'Right to Residence and Relief Under Domestic Violence Act', 'pwdva-protection-residence-rights', 'Women facing domestic abuse have statutory rights to immediate protection orders, residence in shared household, and monetary maintenance.', 'If you face abuse in a domestic relationship, a Magistrate can order the abuser to stay away, prohibit them from throwing you out of the house, and order financial support.', 'The Protection of Women from Domestic Violence Act, 2005 (Sec 12, 18, 19, 20) provides protection, residence, and monetary relief. Satish Chander Ahuja precedent confirmed right to reside in shared home.', 'Any woman in a domestic relationship living in a shared household.', 'Prevents homelessness and physical endangerment of abused women.', 'Kavita was locked out by in-laws. The Magistrate passed an ex-parte residence order directing police escort and Rs. 18,000 monthly maintenance.', '1. Dial Women Helpline 181 or 1091.
2. Contact the District Protection Officer.
3. File application under Section 12 PWDVA before Judicial Magistrate.
4. Seek interim protection, residence, and maintenance orders.', 'Identity proof, Marriage proof, Medical MLC reports (if injured), Photos/recordings of abuse, Income affidavits.', 'Judicial Magistrate First Class (JMFC) / Protection Officer', 'One Stop Centre (Sakhi Scheme) / Women Helpline 181', '1. Domestic Incident Report prepared. 2. Magistrate issues notice in 3 days. 3. Interim orders passed. 4. Case disposed in 60 days.', 'https://www.indiacode.nic.in/handle/123456789/2021', 'Ministry of Women and Child Development, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(104, 1, 'Right of Hindu Daughters to Equal Coparcenary Inheritance', 'daughters-equal-ancestral-property-rights', 'Daughters have the same birthright as sons to ancestral coparcenary property under Hindu Succession Act.', 'As a daughter, you have the exact same legal right to your family ancestral property as your brothers. Marriage does not cancel your inheritance right.', 'Section 6 of Hindu Succession Act, 1956 and Supreme Court Vineeta Sharma v. Rakesh Sharma (2020) established daughter as coparcener by birth with equal shares and liabilities.', 'Hindu, Buddhist, Jain, and Sikh women whose families hold ancestral property.', 'Eliminates gender bias in ancestral succession.', 'Brothers attempted to sell 10 acres ancestral land excluding married sister Deepa. The Civil Court declared the sale void and granted Deepa an equal 1/3rd share.', '1. Collect genealogical tree (kursinama) and land revenue records (Khata/Khatoni).
2. Issue legal notice for partition to coparceners.
3. File Suit for Partition in Civil Court.
4. Apply for interim injunction against illegal sale.', 'Genealogical tree certificate, Ancestral property title deeds, Revenue extracts (7/12, RTC), Identity proof.', 'Civil Court / Sub-Registrar Office', 'State Revenue Land Records Portal', '1. Serve notice. 2. File partition suit. 3. Preliminary decree determining shares. 4. Court Commissioner demarcates land. 5. Final decree.', 'https://www.indiacode.nic.in/handle/123456789/1628', 'Ministry of Law and Justice, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(105, 1, 'Right to Equal Pay for Equal Work Without Gender Discrimination', 'equal-remuneration-and-non-discrimination', 'Employers cannot pay women lower wages or discriminate in hiring and promotion for same or similar work.', 'If a woman and a man do the same work requiring similar skill and effort, the employer must pay equal wages.', 'Under Equal Remuneration Act, 1976 and Section 3 of Code on Wages, 2019, gender discrimination in remuneration or employment terms is illegal.', 'All women workers in corporate, manufacturing, educational, and service sectors.', 'Upholds constitutional equality under Article 39(d).', 'Suniti discovered male peers earned Rs. 20,000 more for the identical role. Citing the Act, her salary was revised retroactively with back-pay.', '1. Review contracts, job descriptions, and salary benchmarks.
2. Submit formal query to HR.
3. File complaint with State Labour Commissioner if unresolved.
4. Claim wage difference arrears before Labour Authority.', 'Employment contract, Job description, Salary slips, Evidence showing identical duties.', 'Labour Commissioner / Labour Court', 'SAMADHAN Labour Dispute Portal', '1. Document disparity. 2. Written grievance. 3. Conciliation proceeding. 4. Recovery of arrears.', 'https://www.indiacode.nic.in/handle/123456789/1785', 'Ministry of Labour and Employment, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(201, 2, 'Right to Statutory Gratuity Payment After 5 Years', 'statutory-gratuity-payment-rights', 'Employees with 5 years continuous service are entitled to statutory gratuity payment upon exit.', 'If you complete 5 years at a firm with 10+ employees, you are entitled to gratuity when leaving (approx 15 days basic salary per year served).', 'Payment of Gratuity Act 1972 Sec 4/7 requires payment within 30 days of exit with 10% compound interest on delayed payment.', 'All employees in establishments with 10+ workers upon resignation, retirement, or retrenchment.', 'Provides post-employment financial safety.', 'Vikram was denied Rs. 2.8L gratuity after 6.5 years. Form N filed before Controlling Authority recovered full sum with 10% interest in 15 days.', '1. Submit Form I to employer upon exit.
2. Allow 30 days for calculation.
3. If unpaid, file Form N before Controlling Authority.
4. Attend hearings for recovery certificate.', 'Appointment letter, Relieving letter, Last salary slip, Form I copy.', 'Controlling Authority (Labour Commissioner)', 'SAMADHAN Labour Portal', '1. Submit Form I. 2. Employer pays in 30 days. 3. If delayed, file Form N. 4. Recovery order issued.', 'https://www.indiacode.nic.in/handle/123456789/1647', 'Ministry of Labour and Employment, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(202, 2, 'Right Against Retrenchment Without Due Process & Severance', 'retrenchment-notice-and-severance-compensation', 'Employees cannot be retrenched without 1 month written notice and statutory severance compensation.', 'Your employer cannot fire you abruptly without legal procedure. You are entitled to 1 month notice/pay plus 15 days pay for each year served.', 'Industrial Disputes Act 1947 Sec 25F sets mandatory preconditions for retrenchment; violations render termination void ab initio.', 'Workmen and employees with 240+ days continuous service.', 'Prevents arbitrary loss of livelihood.', 'Prakash was fired on the spot after 4 years. Challenging it under Sec 25F yielded 2 months notice pay plus 60 days severance settlement.', '1. Do not sign coerced resignations.
2. Demand written termination letter citing legal grounds.
3. Verify notice pay and 15 days/year severance.
4. Lodge dispute before Conciliation Officer.', 'Employment contract, Termination notice, Proof of 240+ days service, Salary slips.', 'Labour Conciliation Officer / Industrial Tribunal', 'State Labour Dispute Redressal Portal', '1. Representation to employer. 2. Dispute before Conciliation Officer. 3. Failure report to Labour Court if needed.', 'https://www.indiacode.nic.in/handle/123456789/1638', 'Ministry of Labour and Employment, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(203, 2, 'Right to Minimum Wages & Double-Rate Overtime Pay', 'statutory-minimum-wages-and-overtime', 'Employees are entitled to state-notified minimum wages and double pay for overtime beyond 8 hours daily.', 'No company can pay below state minimum wage. Overtime work beyond 8 hours/day must be compensated at twice your hourly wage rate.', 'Minimum Wages Act 1948 & Code on Wages 2019 mandate minimum wage floors and overtime at 2x ordinary rates. Penalties up to 10x shortfall.', 'All workers across scheduled industrial and commercial employments.', 'Protects against wage exploitation under Article 23.', 'Rajesh worked 12-hour shifts at Rs. 9,000 against notified Rs. 16,500. Labour Inspector ordered Rs. 4.5L in wage arrears and overtime.', '1. Check state minimum wage notification.
2. Keep records of daily punch-in/out times.
3. Send written grievance to management.
4. File Sec 20 claim before Labour Commissioner.', 'Attendance logs, Biometric exports, Salary slips, State Minimum Wage Notification.', 'Deputy Labour Commissioner', 'State Labour Enforcement Wing', '1. File claim. 2. Employer summoned. 3. Examination of muster rolls. 4. Arrears order with penalty.', 'https://www.indiacode.nic.in/handle/123456789/1898', 'Ministry of Labour and Employment, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(204, 2, 'Right to Employee Provident Fund (EPF) and UAN Portability', 'epf-contribution-and-uan-portability', 'Employees are entitled to 12% matching employer contribution towards EPF and seamless transfer via UAN.', 'Your employer must match your 12% EPF deduction and deposit it with EPFO monthly. Employers cannot deduct both shares from your salary.', 'EPF & MP Act 1952 Sec 6 mandates 12% contribution. Non-deposit is criminal breach of trust under Sec 406/409 IPC.', 'Employees in establishments with 20+ workers earning basic pay up to Rs. 15,000 (and voluntary above).', 'Guarantees retirement corpus and social security.', 'Tanmay noticed employer withheld 8 months PF deposits. Grievance on EPFiGMS triggered Sec 7A inquiry and account credit with compound interest.', '1. Check passbook online with UAN credentials.
2. Query employer finance if deposits missing.
3. Lodge complaint on EPFiGMS (epfigms.gov.in).
4. Enforcement Officers initiate Sec 7A recovery.', 'Salary slips, EPF passbook statement, UAN card, Bank statement.', 'Employees Provident Fund Organisation (EPFO)', 'EPFiGMS Portal (epfigms.gov.in)', '1. Check passbook. 2. File grievance. 3. Sec 7A assessment inquiry. 4. Attachment of employer assets if non-compliant.', 'https://www.epfindia.gov.in', 'EPFO, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(205, 2, 'Right to Safe Working Environment and Injury Compensation', 'workplace-safety-and-injury-compensation', 'Workers injured on duty are entitled to medical care and statutory lump-sum disability compensation.', 'If injured in a workplace accident, your employer or ESIC must provide medical treatment and lump-sum compensation based on disability level.', 'Employees Compensation Act 1923 and ESI Act 1948 make employers strictly liable for compensation in workplace accidents based on wages and age factor.', 'Workers in factories, construction, transport, logistics, and hazardous trades.', 'Enforces employer liability and worker rehabilitation.', 'Mahesh suffered hand injury operating an unguarded press. The Compensation Commissioner awarded Rs. 3.2L in disability compensation plus medical bills.', '1. Report accident immediately to supervisor.
2. Ensure Medico-Legal Certificate (MLC) records work accident.
3. Submit written claim to employer within 2 years.
4. If denied, petition the Compensation Commissioner.', 'Employment proof, Hospital MLC and discharge summary, Disability certificate, Salary proof.', 'Commissioner for Employee Compensation / ESIC', 'ESIC Portal (esic.gov.in)', '1. Accident notice. 2. Medical board assessment. 3. Claim petition before Commissioner. 4. Award within 30 days.', 'https://www.indiacode.nic.in/handle/123456789/2388', 'Ministry of Labour and Employment, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(301, 3, 'Right to 25% Free Admission in Private Schools (RTE Quota)', 'rte-25-percent-private-school-quota', 'Children from economically weaker sections are entitled to 25% free seats in private unaided schools under RTE.', 'Under Section 12(1)(c) of RTE Act, private non-minority schools must reserve 25% entry-level seats for underprivileged children with zero tuition fee.', 'RTE Act 2009 Sec 12(1)(c) mandates 25% entry-level quota for EWS children. Schools are reimbursed by state government.', 'Children aged 6-14 from families earning below state income threshold or disadvantaged social categories.', 'Fulfills Article 21A fundamental right to education.', 'Raju, son of an auto driver, was allotted a seat at a private school via state RTE lottery with free textbooks.', '1. Check annual RTE admission notification on State RTE Portal.
2. Obtain valid Income Certificate and Category Certificate.
3. Register online selecting neighbourhood schools.
4. Submit allotment slip to allotted school.', 'Income Certificate, Category certificate, Child birth certificate, Address proof.', 'District Education Officer (DEO)', 'State RTE Admission Portal', '1. Online application. 2. Computerized allotment. 3. Verification. 4. Free admission confirmed.', 'https://dsel.education.gov.in/rte', 'Department of School Education and Literacy, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(302, 3, 'Protection Against Ragging in Colleges and Universities', 'anti-ragging-protections-ugc', 'Students have the right to a ragging-free campus with zero tolerance; colleges must file FIR within 24 hours of complaint.', 'Ragging in any form is a punishable criminal offense. Colleges must have Anti-Ragging Committees.', 'UGC Regulations 2009 make heads of institutions criminally liable under IPC if they fail to file an FIR within 24 hours of a ragging incident.', 'All students in higher educational institutions in India.', 'Protects human dignity and safety in higher education.', 'First-year student Sahil was harassed in the hostel. A complaint to National Anti-Ragging Helpline triggered immediate FIR and suspension.', '1. Call 24x7 Anti-Ragging Helpline 1800-180-5522.
2. Lodge online complaint on antiragging.in.
3. Submit written complaint to college squad.
4. Head of college must report to police in 24 hours.', 'Written grievance, College ID card, Audio/video proof (if any), Witness details.', 'Anti-Ragging Helpline / UGC Cell', 'antiragging.in National Portal', '1. Helpline registers complaint. 2. Automated SMS alert to VC/Principal. 3. Police probe in 24 hours. 4. Action taken.', 'https://www.antiragging.in', 'University Grants Commission (UGC), Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(303, 3, 'Right to Immediate Issuance of Degree & Marksheets (No Withholding)', 'prohibition-withholding-degrees-marksheets', 'Universities cannot withhold student original degree certificates or marksheets over fee disputes.', 'Your college cannot hold your original 10th/12th/Graduation certificates hostage over pending fees or campus disputes.', 'UGC Notification on Verification of Certificates prohibits educational institutions from retaining original academic certificates.', 'All students graduating from UGC/AICTE-recognized institutions.', 'Prevents career disruption and illegal certificate detention.', 'College withheld Shreya original certificates demanding campus fee. Legal notice citing UGC rules compelled release in 48 hours.', '1. Submit formal written application for certificate return.
2. Cite UGC Public Notice.
3. Lodge grievance on UGC e-Samadhan portal.
4. If denied, file consumer complaint.', 'Fee receipts, College ID card, Completion certificate, Return application copy.', 'UGC e-Samadhan Cell / Vice-Chancellor', 'UGC e-Samadhan (samadhan.ugc.ac.in)', '1. Written demand. 2. e-Samadhan grievance. 3. UGC notice. 4. Release within 7 days.', 'https://samadhan.ugc.ac.in', 'University Grants Commission, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(304, 3, 'Right to Fee Refund on College Admission Withdrawal', 'college-admission-cancellation-fee-refund', 'Students withdrawing admission before or near course commencement are entitled to proportional fee refund under UGC mandates.', 'If you cancel admission before classes start or within designated refund windows, college must refund fees after max Rs. 1,000 processing fee.', 'UGC Fee Refund Policy mandates 100% refund up to 15 days before formally notified admission closure date.', 'All students admitted to UGC-recognized universities and colleges.', 'Prevents financial exploitation of students.', 'Aditya secured seat in NIT and withdrew from private university 10 days before term start; full Rs. 1.4L refunded after notice.', '1. Submit formal admission cancellation in writing.
2. Cite UGC Fee Refund Guidelines.
3. Request refund to original bank account.
4. Lodge complaint on UGC e-Samadhan if refused.', 'Allotment letter, Fee receipt, Cancellation application, Bank passbook copy.', 'University Grievance Redressal Committee / UGC', 'UGC e-Samadhan (samadhan.ugc.ac.in)', '1. Cancellation request. 2. Verification. 3. Refund in 30 days. 4. UGC action if non-compliant.', 'https://www.ugc.gov.in', 'University Grants Commission, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(305, 3, 'Right to Transparent Evaluation & Answer Script Inspection (RTI)', 'student-answer-sheet-inspection-rti', 'Examinees have the legal right to inspect and obtain certified copies of evaluated answer sheets under RTI Act.', 'You have the legal right to see your checked exam paper. Exam boards cannot refuse showing your answer sheets.', 'Supreme Court in CBSE v. Aditya Bandopadhyay held evaluated answer sheets are information under Sec 2(f) of RTI Act.', 'All students appearing in state boards, CBSE, universities, and public competitive exams.', 'Promotes evaluation transparency and accountability.', 'Neha received surprisingly low marks in semester exam; RTI application under Sec 6 revealed an uncounted 14-mark question.', '1. File RTI application within 30 days of results.
2. Pay statutory Rs. 10 fee to PIO.
3. Specify roll number, subject code, and exam centre.
4. Receive certified photocopies in 30 days.', 'Admit card, Marksheet copy, RTI application form, Fee receipt.', 'Public Information Officer (PIO) of Board / University', 'RTI Online Portal (rtionline.gov.in)', '1. Submit RTI. 2. Verification. 3. Photocopy fee payment. 4. Certified copies dispatched in 30 days.', 'https://rtionline.gov.in', 'Department of Personnel and Training (DoPT), Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(401, 4, 'Right to Emergency Medical Stabilization Without Advance Deposit', 'emergency-medical-care-without-deposit', 'All hospitals are legally mandated to provide immediate emergency care without demanding upfront deposit.', 'In life-threatening emergencies or road crashes, hospitals cannot refuse treatment or demand advance money before stabilizing the patient.', 'Supreme Court in Pt. Parmanand Katara v. Union of India and Clinical Establishments Act 2010 Sec 12(2) establish absolute legal duty to stabilize emergency patients.', 'Every citizen in need of emergency or critical medical care.', 'Upholds Article 21 Right to Life.', 'Suraj was brought unconscious after a crash. Hospital was legally required to stabilize him in ICU without demanding advance cash deposit.', '1. Demand immediate emergency triage.
2. Cite Clinical Establishments Act and Parmanand Katara precedent if deposit demanded.
3. Request hospital CMO or administrator.
4. Lodge grievance if denied.', 'Admission slip, Hospital MLC report, Medical chart, Correspondence with hospital.', 'State Clinical Establishment Council / State Medical Council', 'National Health Portal (nhp.gov.in)', '1. Immediate triage. 2. Stabilization. 3. Counseling. 4. Action against hospital for refusal.', 'https://www.nhp.gov.in', 'Ministry of Health and Family Welfare, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(402, 4, 'Right to Access Complete Medical Records Within 72 Hours', 'access-to-medical-records-72-hours', 'Patients or their representatives have the legal right to obtain complete copies of medical records within 72 hours of request.', 'You have the right to get copies of your medical records, test reports, doctor notes, and bills within 72 hours of asking the hospital.', 'National Medical Commission (NMC) Regulations 2002 Clause 1.3.2 states every physician must maintain indoor records and furnish copies within 72 hours on request.', 'All inpatients and outpatients across private clinics and hospitals.', 'Empowers patients to seek second opinions.', 'Priya requested discharge summary and lab reports for second opinion. Hospital delayed 10 days. NMC grievance compelled delivery in 24 hours.', '1. Submit written request to Medical Records Department (MRD).
2. Specify patient name, IPD number, and admission dates.
3. Pay reasonable photocopy charge.
4. File complaint with State Medical Council if denied.', 'Patient ID / Discharge card, Written application, Identity proof.', 'Medical Superintendent / State Medical Council', 'State Medical Council Grievance Cell', '1. Request to MRD. 2. 72-hour statutory window. 3. Delivery of records. 4. Penalty for non-compliance.', 'https://www.nmc.org.in', 'National Medical Commission, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(403, 4, 'Right to Informed Consent and Transparent Itemized Billing', 'informed-consent-and-itemized-billing', 'Patients have the right to understand treatment risks and alternatives, and receive clear, itemized bills without hidden markups.', 'Doctors must explain surgical risks, alternatives, and costs in simple language before operating. Hospitals cannot charge hidden fees.', 'Charter of Patient Rights (NHRC/MoHFW) mandates informed written consent and itemized billing displaying consumables, medicines, and room rates.', 'All patients admitted to clinical establishments in India.', 'Protects patient autonomy and prevents billing fraud.', 'Farhan audited hospital bill line-by-line and identified Rs. 85,000 in unitemized consumable charges for unused items, obtaining full refund.', '1. Read informed consent forms before signature.
2. Request itemized estimate in writing.
3. Audit discharge bill line-by-line.
4. Challenge unfair billing at Consumer Commission.', 'Informed consent form, Pre-admission estimate, Itemized hospital bill, Pharmacy receipts.', 'Hospital Grievance Cell / DCDRC', 'National Consumer Helpline (1915)', '1. Demand itemized bill. 2. Written protest. 3. Dispute on e-Daakhil. 4. Refund plus compensation.', 'https://main.mohfw.gov.in', 'Ministry of Health and Family Welfare, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(404, 4, 'Prohibition on Detaining Patients or Bodies for Unpaid Bills', 'prohibition-detaining-patients-unpaid-bills', 'Hospitals cannot hold patients or deceased bodies captive or refuse discharge over unpaid medical bills.', 'A hospital cannot physically detain a cured patient or hold a dead body hostage demanding payment. Such actions constitute illegal confinement.', 'Delhi High Court in Devesh Sharma v. State and NHRC guidelines established that dead bodies or patients cannot be detained for financial recovery.', 'All patients and families in private nursing homes and hospitals.', 'Protects human dignity in life and death under Article 21.', 'Hospital held mortal remains of an elder over pending Rs. 60,000 ICU bill. Police intervention citing High Court directives compelled immediate handover.', '1. Inform administration that detaining bodies is illegal confinement.
2. Call Police (112) for immediate assistance.
3. Lodge grievance with Chief Medical Officer (CMO).
4. File urgent writ before High Court or Human Rights Commission.', 'Admission slip, Death summary / Discharge certificate, Correspondence regarding billing, Police DD entry.', 'District Magistrate / CMO / Police (112)', 'State Human Rights Commission', '1. Demand release. 2. Police intervention. 3. Body released. 4. Civil recovery only.', 'https://nhrc.nic.in', 'National Human Rights Commission (NHRC)', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(405, 4, 'Right to Confidential Mental Healthcare & Insurance Parity', 'mental-healthcare-act-insurance-parity', 'Persons with mental illness have the right to confidentiality, dignity, and health insurance coverage on par with physical ailments.', 'Health insurance companies cannot exclude mental illness from coverage. Your psychiatric treatment records must remain strictly confidential.', 'Mental Healthcare Act 2017 Section 21 mandates health insurers to provide mental illness coverage on the same terms as physical conditions.', 'All individuals diagnosed with or undergoing treatment for mental health conditions.', 'Guarantees equitable healthcare financing.', 'Siddharth was denied insurance reimbursement for inpatient psychiatric care. Complaint with Insurance Ombudsman ordered full claim settlement with interest.', '1. Review policy terms against IRDAI circular.
2. Submit claim with psychiatrist clinical summary.
3. If rejected, file internal grievance with Insurer.
4. Escalate to Insurance Ombudsman (cioins.co.in).', 'Insurance policy, Inpatient records, Psychiatrist clinical notes, Rejection letter.', 'Insurance Ombudsman / Mental Health Review Board', 'Council for Insurance Ombudsmen (cioins.co.in)', '1. Claim submission. 2. Rejection protest. 3. Complaint before Ombudsman. 4. Award within 3 months.', 'https://irdai.gov.in', 'Insurance Regulatory and Development Authority of India (IRDAI)', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(501, 5, 'Right of Homebuyer to Possession Timeline & Delayed Interest', 'homebuyer-rera-delayed-possession-interest', 'Homebuyers are entitled to timely possession or monthly interest at SBI MCLR + 2% for project delays under RERA.', 'If a builder delays your flat possession past the agreed date, you have the right to either get a full refund with interest or monthly interest for every month of delay.', 'Section 18 of RERA Act, 2016 gives allottees the unconditional right to withdraw and claim full refund with interest, or stay in project and receive monthly compensation interest.', 'All homebuyers purchasing flats, plots, or commercial units in RERA-registered projects.', 'Protects life savings against builder fraud and construction delays.', 'Kunal flat was delayed by 3 years. Filing a complaint before State RERA Authority granted him Rs. 28,000 monthly delayed interest until handover.', '1. Verify builder RERA registration on State RERA portal.
2. Gather Agreement for Sale and payment receipts.
3. File formal complaint on State RERA portal.
4. Attend hearings for refund or delayed interest order.', 'Agreement for Sale, Allotment letter, Bank payment proofs, Builder demand letters, Possession delay notices.', 'State Real Estate Regulatory Authority (RERA)', 'State RERA Online Portal', '1. File online RERA complaint. 2. Notice to builder. 3. Adjudication. 4. Recovery warrant issued to Collector if unpaid.', 'https://mohua.gov.in', 'Ministry of Housing and Urban Affairs, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(502, 5, 'Tenant Protection Against Arbitrary Eviction & Utility Cut', 'tenant-protection-against-unlawful-eviction', 'Tenants cannot be forcefully evicted without statutory notice and landlord cannot disconnect water or electricity.', 'Your landlord cannot lock you out, disconnect power/water, or throw your belongings out without a court/Rent Authority eviction order.', 'Model Tenancy Act 2021 and State Rent Control Acts prohibit landlords from withholding essential services and mandate 30 days written notice on valid statutory grounds.', 'All residential and commercial tenants with valid lease agreements.', 'Protects peaceful possession and human dignity against landlord harassment.', 'Landlord disconnected electricity to force tenant out before lease end. Rent Authority directed immediate power restoration and imposed Rs. 10,000 fine on landlord.', '1. Retain signed copy of Rent Agreement and rent payment receipts.
2. If utilities cut, lodge police complaint for wrongful restraint/nuisance.
3. File application before Rent Authority for restoration.
4. Landlord must give 30 days notice on legally permitted grounds.', 'Rent Agreement, Rent bank transfer receipts, Move-in inventory, Photographs/video of utility tampering.', 'Rent Authority / Rent Court / Civil Court', 'State Rent Control Department', '1. Notice to landlord. 2. Application to Rent Authority. 3. Summary inquiry. 4. Immediate utility restoration order.', 'https://mohua.gov.in', 'Ministry of Housing and Urban Affairs, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(503, 5, 'Right to Security Deposit Refund Within 30 Days of Vacating', 'tenant-security-deposit-refund-30-days', 'Landlords must return tenant security deposit within 30 days of handing over vacant possession.', 'When you move out and hand over keys, the landlord must refund your security deposit within 30 days, deducting only genuine documented damages or unpaid bills.', 'Under Model Tenancy Act Section 10, security deposit for residential premises is capped at 2 months rent and must be returned within 30 days of vacating after agreed deductions.', 'All residential and commercial tenants vacating rented premises.', 'Prevents arbitrary withholding of tenant funds.', 'Owner refused to return Rs. 70,000 deposit citing painting costs. Tenant issued legal notice with move-out inspection video, recovering full deposit plus interest.', '1. Perform joint move-out inspection with landlord.
2. Take video of property condition on handover day.
3. Send written demand for deposit refund giving 15 days.
4. If unpaid, file petition before Rent Authority.', 'Rent Agreement, Deposit payment bank proof, Move-out handover video/acknowledgment, Utility bill clearance receipts.', 'Rent Authority / Small Causes Court', 'District Rent Dispute Tribunal', '1. Move-out notice. 2. Key handover. 3. Written deposit demand. 4. Rent Authority summons landlord and orders refund.', 'https://mohua.gov.in', 'Ministry of Housing and Urban Affairs, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(504, 5, 'Right to Public Inspection of Title Deeds & Encumbrance Certificates', 'property-title-search-encumbrance-certificate', 'Citizens have the statutory right to inspect public land records and obtain certified Encumbrance Certificates (EC).', 'Before buying land or property, you have the legal right to check its ownership history, mortgages, and court attachments at the Sub-Registrar office.', 'Section 57 of the Registration Act, 1908 allows any person to inspect Book 1 records and obtain certified copies of registered deeds and Encumbrance Certificates (EC).', 'All property buyers, owners, and legal heirs verifying property titles.', 'Prevents real estate fraud and double-sale scams.', 'Nitin applied for an online 30-year EC and discovered a registered bank mortgage on a flat the seller claimed was loan-free, averting a Rs. 50L fraud.', '1. Obtain property survey number, village/ward name, and boundary details.
2. Apply online for 30-year Encumbrance Certificate (EC) on State Registration Portal.
3. Apply for certified copy of mother deeds.
4. Consult a property lawyer for title search report.', 'Survey number / Plot details, Previous sale deed copy, Application form, State portal search fee receipt.', 'Sub-Registrar Office / Department of Stamps & Registration', 'State Online Property Registration Portal (IGRS / Kaveri / Meebhoomi)', '1. Search index. 2. Fee payment. 3. EC generated showing all registered transactions. 4. Certified deed copies issued.', 'https://dor.gov.in', 'Department of Revenue, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(505, 5, 'Right of Co-Owners to Partition and Separate Possession', 'co-owners-property-partition-suit', 'Any co-owner of joint or undivided property has the legal right to demand physical partition and separate registered possession.', 'If you own property jointly with family or partners and want your demarcated share, you can file a partition suit in civil court.', 'Under the Partition Act, 1893 and Transfer of Property Act, 1882, any co-owner can institute a suit for partition. If physical division is impractical, the court can auction the property among co-owners.', 'All co-owners, coparceners, and tenants-in-common holding undivided real estate.', 'Ensures individual property rights and prevents majority dominance.', 'Three cousins inherited a commercial building. Two refused to give the third his share. The Civil Court passed a preliminary decree and appointed a Court Commissioner to divide the property.', '1. Collect title deeds, revenue records, and tax receipts.
2. Send a formal legal notice for amicable partition.
3. File Suit for Partition in the competent Civil Court.
4. Court passes preliminary decree determining shares, followed by final demarcation.', 'Title deed / Will / Succession certificate, Mutation extract, Property tax receipts, Site plan with boundaries.', 'Civil Court of Competent Jurisdiction', 'District Civil Court Complex', '1. Legal notice. 2. Partition suit filed. 3. Preliminary decree. 4. Court Commissioner survey. 5. Final decree and separate registration.', 'https://www.indiacode.nic.in/handle/123456789/2250', 'Ministry of Law and Justice, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(601, 6, 'Right to Claim Monthly Maintenance for Spouses and Children', 'maintenance-claim-crpc-125-bnss', 'Spouses, children, and parents unable to maintain themselves have the statutory right to monthly maintenance.', 'If your spouse has deserted or neglects you and you cannot support yourself, the court can order them to pay monthly maintenance based on their income.', 'Section 125 of CrPC (Section 144 BNSS) and Hindu Adoptions and Maintenance Act 1956 provide speedy monthly maintenance. Supreme Court in Rajnesh v. Neha mandated comprehensive income disclosure.', 'Dependent spouses, minor children, major children with disability, and elderly parents.', 'Prevents destitution and homelessness among vulnerable family members.', 'A dependent mother of two was deserted without financial support. The Family Court ordered interim maintenance of Rs. 25,000/month within 60 days based on the husband salary slip.', '1. File an application under Section 125 CrPC / 144 BNSS in Family Court.
2. Submit comprehensive Income & Asset Affidavit as per Supreme Court format.
3. Seek interim maintenance during pendency of trial.
4. Court passes monthly maintenance order executable through salary attachment.', 'Marriage certificate, Children birth certificates, Income and Asset Affidavit, Bank statements, Proof of spouse income.', 'Family Court / Judicial Magistrate', 'eCourts Services Portal (ecourts.gov.in)', '1. Application filed. 2. Notice to respondent. 3. Interim maintenance hearing. 4. Final maintenance order.', 'https://www.indiacode.nic.in/handle/123456789/16225', 'Ministry of Law and Justice, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(602, 6, 'Child Custody Governed by Best Interest of the Child Doctrine', 'child-custody-best-interest-doctrine', 'Custody and guardianship disputes are decided strictly based on the welfare and best interest of the child, not parental rights.', 'In parental separation, courts do not treat children as property. The parent who can provide better emotional, moral, and educational care gets primary custody, with visitation for the other.', 'Under Guardians and Wards Act 1890 Sec 17 and Hindu Minority and Guardianship Act 1956 Sec 13, the welfare of the minor child is the paramount consideration.', 'Parents and legal guardians involved in separation or custody litigation.', 'Protects child psychological well-being and stability.', 'Father claimed sole custody citing higher income. The court awarded primary custody to the mother based on the 4-year-old emotional bond and granted the father weekend visitation rights.', '1. File petition for custody/guardianship under Guardians and Wards Act.
2. Emphasize child schooling, emotional stability, and family environment.
3. Request interim visitation rights to maintain parental bonding.
4. Court may interview child in chamber before deciding.', 'Child birth certificate, School records and report cards, Medical history records, Financial capability proofs.', 'Family Court / Principal Senior Civil Judge', 'eCourts Family Court Wing', '1. Custody petition filed. 2. Mediation referral. 3. Interim visitation arrangement. 4. Final custody and parenting plan order.', 'https://www.indiacode.nic.in/handle/123456789/2288', 'Ministry of Law and Justice, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(603, 6, 'Right to Mutual Consent Divorce Without Protracted Delay', 'mutual-consent-divorce-speedy-cooling-waiver', 'Couples mutually agreeing to separate can obtain divorce within 6 months, and the 6-month cooling period can be waived.', 'If both husband and wife mutually agree that the marriage cannot work, they can file a joint petition for divorce and settle custody and alimony amicably.', 'Under Section 13B of Hindu Marriage Act 1955 and Section 28 of Special Marriage Act 1954, mutual consent divorce requires 1-year separation. Supreme Court in Amardeep Singh v. Harveen Kaur held the 6-month cooling period can be waived.', 'Legally married couples mutually agreeing to dissolve marriage.', 'Enables dignified separation without protracted, acrimonious litigation.', 'Couples living separately for 2 years agreed on alimony and assets. They filed a joint mutual consent petition and obtained cooling period waiver, finalizing divorce in 3 weeks.', '1. Prepare comprehensive Memorandum of Settlement detailing alimony and custody.
2. File Joint Petition for Mutual Consent Divorce (First Motion).
3. Record statements before the Family Court Judge.
4. Apply for waiver of 6-month cooling period or move Second Motion after 6 months.', 'Marriage certificate, Photographs of marriage, Address proofs, Joint settlement agreement, Income affidavits.', 'Family Court / District Court', 'eCourts Portal (ecourts.gov.in)', '1. First Motion filed. 2. Statements recorded. 3. Waiver application (if eligible). 4. Second Motion and final decree of divorce.', 'https://www.indiacode.nic.in/handle/123456789/1572', 'Ministry of Law and Justice, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(604, 6, 'Protection of Matrimonial Residence in Shared Household', 'protection-residence-matrimonial-home', 'A woman cannot be dispossessed or evicted from her matrimonial shared household by husband or in-laws without due process of law.', 'Even if the house belongs to your father-in-law or husband, your in-laws cannot throw you out on the street. You have the statutory right to reside in the shared household.', 'Under Section 17 of PWDVA 2005 and Supreme Court in Satish Chander Ahuja v. Sneha Ahuja (2020), every woman in a domestic relationship has the right to reside in the shared household.', 'Married women and women in domestic relationships living in matrimonial or shared homes.', 'Prevents arbitrary marital eviction and destitution.', 'In-laws locked out daughter-in-law while husband was abroad. Magistrate issued an urgent injunction restraining them from disturbing her peaceful possession.', '1. File an urgent application under Section 19 PWDVA before the Magistrate.
2. Seek protection against eviction and an order for keys/possession.
3. Request local police protection to prevent forceful lockout.
4. Magistrate can also direct alternative rented accommodation paid by respondent.', 'Marriage proof, Domestic Incident Report, Photos showing residence, Police complaint copy (if locked out).', 'Judicial Magistrate First Class / Family Court', 'District Legal Services Authority (DLSA)', '1. Application under Sec 19. 2. Urgent hearing in 48 hours. 3. Protection Officer and Police enforce possession order.', 'https://www.indiacode.nic.in/handle/123456789/2021', 'Ministry of Women and Child Development, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(605, 6, 'Right to Legal Child Adoption Through CARA Framework', 'legal-child-adoption-cara-framework', 'Prospective parents and children have the legal right to secure, transparent adoption governed by CARA, creating full legal parent-child relationship.', 'Adopting a child must be done through CARA (Central Adoption Resource Authority). Direct informal adoptions without court/CARA orders are illegal and punishable.', 'Under Juvenile Justice Act 2015 Sections 56-73, all adoptions in India must comply with CARA regulations. A finalized adoption order makes the adopted child equal in inheritance and legal rights as a biological child.', 'Prospective adoptive parents (married couples or single individuals) meeting eligibility criteria.', 'Protects child welfare, prevents child trafficking, and gives undeniable legal identity.', 'Rohan and Neha registered on CARINGS portal. After home study by Specialized Adoption Agency and District Magistrate approval, they legally welcomed a 2-year-old child with full inheritance rights.', '1. Register online on CARINGS portal (cara.wcd.gov.in).
2. Specialized Adoption Agency (SAA) conducts Home Study Report (HSR).
3. Child referral and reserve matching based on preferences.
4. District Magistrate issues final legal adoption order.', 'Birth certificates, Marriage certificate (if couple), Medical fitness certificates, Income tax returns (3 years), Police verification report.', 'Central Adoption Resource Authority (CARA) / District Magistrate', 'CARINGS Portal (cara.wcd.gov.in)', '1. Online registration. 2. Home study approval. 3. Child matching. 4. Pre-adoption foster care. 5. DM adoption order.', 'https://cara.wcd.gov.in', 'Ministry of Women and Child Development, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(701, 7, 'Right to Return Defective Goods & Full Refund', 'right-to-return-defective-goods-and-full-refund', 'Consumers have statutory rights to replacement, repair, or full refund for defective goods and deficient commercial services.', 'When you buy any product and it turns out broken or not as promised, the seller/brand is legally bound to replace it or give a full refund.', 'Section 2(9) and Section 35 of Consumer Protection Act 2019 grant comprehensive rights against unfair trade practices and product defects. No-refund clauses are void.', 'All citizens purchasing goods or services for personal consideration online or offline.', 'Protects consumers from commercial exploitation.', 'Pooja washing machine broke on Day 2. E-commerce seller refused return. NCH complaint (1915) resulted in full brand replacement in 48 hours.', '1. Document defect with photos, unboxing video, and tax invoice.
2. Lodge complaint with seller in writing.
3. Call 1915 or register on consumerhelpline.gov.in.
4. File e-Daakhil consumer complaint before District Commission if unresolved.', 'Tax invoice, Warranty card, Photos/videos of defect, Merchant chat transcripts.', 'District Consumer Disputes Redressal Commission (DCDRC)', 'National Consumer Helpline (1915 / consumerhelpline.gov.in)', '1. NCH grievance. 2. Brand mediation. 3. If failed, e-Daakhil complaint. 4. Commission orders refund plus compensation.', 'https://consumerhelpline.gov.in', 'Department of Consumer Affairs, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(702, 7, 'Protection Against Dark Patterns & Misleading E-Commerce Ads', 'dark-patterns-and-misleading-advertisements', 'Consumers are protected from manipulative digital design tricks like drip pricing, forced add-ons, and fake urgency.', 'Websites cannot trick you into buying subscriptions, add hidden fees at the final payment screen, or use countdown timers to deceive you.', 'Central Consumer Protection Authority (CCPA) Guidelines 2023 define 13 prohibited dark patterns including False Urgency, Basket Sneaking, Confirm Shaming, and Forced Action as unfair trade practices.', 'All online shoppers and digital app users in India.', 'Guarantees fair choice and transparent pricing in digital commerce.', 'Travel booking app sneaked insurance into cart and charged convenience fees at final step. CCPA complaint compelled fee refund and removal of pre-ticked boxes.', '1. Take screenshots of deceptive pricing, hidden add-ons, or cancellation hurdles.
2. Raise written objection with merchant customer care.
3. Report dark pattern on National Consumer Helpline portal.
4. CCPA can impose fines up to Rs. 10 Lakhs on offenders.', 'Screenshots of checkout steps, Final invoice showing hidden charges, App screen recording.', 'Central Consumer Protection Authority (CCPA)', 'National Consumer Helpline (consumerhelpline.gov.in)', '1. Report dark pattern. 2. CCPA notices to platform. 3. Discontinuation of deceptive design. 4. Restitution to affected consumers.', 'https://consumeraffairs.nic.in', 'Department of Consumer Affairs, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(703, 7, 'Right to Compensation for Deficient Commercial Services', 'compensation-for-deficient-services-cpa', 'Consumers are entitled to compensation for deficiency in banking, courier, aviation, insurance, and telecommunication services.', 'If an airline loses your luggage, a courier misplaces important documents, or a bank wrongfully delays transactions, you can claim damages.', 'Section 2(11) of Consumer Protection Act 2019 defines deficiency as any fault, imperfection, or inadequacy in service quality, entitling consumers to compensation.', 'All individuals paying consideration for professional, financial, or commercial services.', 'Enforces service quality and accountability across service sectors.', 'Courier lost original educational certificates sent for job interview. Consumer Commission awarded Rs. 1.2L compensation for mental agony and loss of opportunity.', '1. Preserve consignment note, booking receipt, and service agreement.
2. Send formal written demand letter to customer care giving 15 days.
3. Lodge grievance on National Consumer Helpline (1915).
4. File claim on e-Daakhil before District Consumer Commission.', 'Booking receipt, Service contract, Proof of damage/loss, Written grievance correspondence.', 'District Consumer Commission (DCDRC) / Sectoral Ombudsman', 'e-Daakhil Portal (edaakhil.nic.in)', '1. Notice to provider. 2. e-Daakhil filing. 3. Commission summons respondent. 4. Award of refund and damages.', 'https://edaakhil.nic.in', 'National Consumer Disputes Redressal Commission (NCDRC)', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(704, 7, 'Strict Product Liability Redressal Against Manufacturers', 'strict-product-liability-cpa-2019', 'Manufacturers and sellers are strictly liable to compensate consumers for physical harm or property damage caused by dangerous or flawed products.', 'If an appliance explodes, food product causes poisoning, or phone battery catches fire, the manufacturer must pay for all injuries and property damages.', 'Chapter VI (Sections 84-87) of Consumer Protection Act 2019 introduced statutory Product Liability. Strict liability applies without needing to prove manufacturer negligence.', 'Any consumer or bystander injured by defective products.', 'Ensures industrial safety standards and holds global manufacturers accountable.', 'A smartphone battery exploded while charging, injuring a student hand. The Consumer Commission awarded Rs. 5.5L product liability compensation against the manufacturer.', '1. Preserve defective product, original packaging, and purchase invoice.
2. Document injuries with hospital records and doctor certificates.
3. Take photographs of damaged property.
4. File product liability claim before Consumer Commission.', 'Purchase invoice, Physical defective item, Medical records and doctor certificates, Photos of damage.', 'Consumer Commission / Central Consumer Protection Authority', 'e-Daakhil Portal', '1. File claim with medical proof. 2. Laboratory testing of product. 3. Strict liability adjudication. 4. Compensation award.', 'https://consumeraffairs.nic.in', 'Department of Consumer Affairs, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(705, 7, 'Right to File Online Consumer Case via e-Daakhil Without Lawyer', 'file-consumer-complaint-edaakhil-without-lawyer', 'Citizens can file and argue consumer cases online from home using the e-Daakhil portal without needing an advocate.', 'You do not need to hire a lawyer to fight for your consumer rights. You can draft your own complaint, pay a nominal online court fee, and attend virtual hearings.', 'Consumer Protection Act 2019 and e-Daakhil system empower consumers to file complaints electronically from anywhere, pay online fees, and represent themselves as party-in-person.', 'Any aggrieved consumer seeking dispute redressal up to Rs. 50 Lakhs (District Commission).', 'Democratizes justice and eliminates advocate dependency for small claims.', 'A citizen denied a Rs. 12,000 hotel refund filed an e-Daakhil petition himself in 20 minutes, won the case in 3 hearings, and recovered the full refund plus Rs. 5,000 costs.', '1. Register as Citizen on edaakhil.nic.in using Aadhaar/PAN.
2. Draft simple facts: what happened, defect/deficiency, relief sought.
3. Upload invoice and correspondence in PDF.
4. Pay nominal court fee via Bharatkosh and track hearing dates.', 'Purchase invoice / Payment proof, Written notice to seller, Written reply (if any), Aadhaar ID copy.', 'District Consumer Commission', 'e-Daakhil Portal (edaakhil.nic.in)', '1. Online registration. 2. Upload petition. 3. Scrutiny in 48 hours. 4. Notice issued. 5. Virtual or physical hearing.', 'https://edaakhil.nic.in', 'NCDRC, Department of Consumer Affairs', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(801, 8, 'Protection Against Online Financial Fraud and 1930 Helpline Interception', 'protection-against-online-financial-fraud-1930', 'Victims of unauthorized digital transactions are entitled to immediate transaction freezing via 1930 and bank refund under RBI rules.', 'If someone steals money from your bank account through UPI fraud or phishing, reporting it on Helpline 1930 within the golden hour freezes the money in transit.', 'RBI Circular on Limiting Customer Liability and IT Act Sec 66D establish zero customer liability if reported within 3 days. I4C platform intercepts fund routing.', 'All bank account holders, UPI users, and cardholders in India.', 'Protects citizens against cyber financial loss.', 'Arjun lost Rs. 75,000 in an electricity bill SMS phishing scam. Calling 1930 in 40 minutes intercepted the fraud account and reversed the entire amount.', '1. Call National Cyber Helpline 1930 immediately.
2. Block card/account via banking app or phone.
3. Register full incident report on cybercrime.gov.in.
4. Submit copy of Cyber FIR Acknowledgement to home branch within 3 days.', 'Bank statement showing debit, Screenshot of fraud SMS/URL, Transaction Reference (UTR/UPI Ref), Cyber Crime Acknowledgement.', 'Indian Cyber Crime Coordination Centre (I4C) & Bank Ombudsman', 'National Cyber Crime Reporting Portal (cybercrime.gov.in)', '1. Dial 1930 to freeze funds. 2. File cybercrime.gov.in report. 3. Branch submission. 4. RBI zero-liability refund.', 'https://cybercrime.gov.in', 'Ministry of Home Affairs, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(802, 8, 'Protection Against Non-Consensual Image Leaks & Cyberstalking', 'cyberstalking-and-nonconsensual-image-protection', 'Victims of online stalking, morphing, or non-consensual image sharing have the right to mandatory 24-hour takedown and criminal prosecution.', 'If anyone shares private photos, morphs pictures, or stalks you online, police must register an FIR and social media platforms must remove the content within 24 hours.', 'Section 66E/67A of IT Act 2000 and IT Rules 2021 mandate social media intermediaries to take down non-consensual intimate imagery within 24 hours of notification.', 'All individuals facing online harassment, morphing, blackmails, or digital stalking.', 'Protects bodily privacy and personal dignity under Article 21.', 'A woman was blackmailed by an ex-partner threatening to post private photos. Cyber police registered an FIR and issued an emergency takedown notice, purging all links within 12 hours.', '1. Do not delete chats, usernames, profile URLs, or timestamps.
2. Report immediately under "Report Cybercrime Against Women/Children" on cybercrime.gov.in.
3. Submit report to social media platform Grievance Officer.
4. Call 1930 or visit local Cyber Police Station for FIR.', 'Screenshots of harassing messages, Account handles/URLs, Message headers, Incident chronology.', 'Cyber Crime Police Station / Platform Grievance Officer', 'National Cybercrime Portal / StopNCII.org', '1. Emergency portal report. 2. Intermediary 24-hr takedown. 3. Cyber FIR registration. 4. Accused arrest and digital forensics.', 'https://cybercrime.gov.in', 'Ministry of Home Affairs / MeitY', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(803, 8, 'Right to Erasure, Correction & Grievance Redressal Under DPDP Act', 'dpdp-act-data-erasure-and-correction', 'Citizens have statutory rights to view what personal data apps hold, correct mistakes, and withdraw consent demanding data erasure.', 'You have the legal right to ask companies what data they have about you, correct wrong details, and delete your account and personal history permanently.', 'Sections 12 and 13 of the Digital Personal Data Protection Act, 2023 grant Data Principals enforceable rights to access, correction, erasure, and grievance redressal against Data Fiduciaries.', 'All digital citizens whose personal data is processed by apps, websites, and companies.', 'Restores personal data ownership and privacy autonomy.', 'An e-commerce platform refused to delete credit card information and phone records after account closure. Notice citing DPDP Act compelled complete data deletion within 7 days.', '1. Review app privacy settings and consent dashboards.
2. Submit formal Data Correction or Erasure request to Data Protection Officer (DPO).
3. Company must resolve request within prescribed statutory period.
4. Escalate to Data Protection Board of India if company refuses.', 'Copy of written erasure request to DPO, App account details, Company response/rejection.', 'Data Protection Board of India / Company DPO', 'Data Protection Board Online Portal', '1. Request to company DPO. 2. Company response within 30 days. 3. If dissatisfied, appeal to Data Protection Board. 4. Penalties on company.', 'https://www.meity.gov.in', 'Ministry of Electronics and Information Technology, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(804, 8, 'Protection Against SIM Swapping and Unauthorized Mobile Connections', 'sim-swapping-and-sanchar-saathi-tafcop', 'Citizens have the right to check all SIM cards issued in their name and block unauthorized numbers or stolen mobile handsets.', 'You can check how many mobile numbers are active in your name using the government Sanchar Saathi portal, and block unknown SIM cards immediately.', 'Department of Telecommunications (DoT) Sanchar Saathi initiative (TAFCOP and CEIR modules) provides real-time tracking of mobile numbers registered against a citizen Aadhaar and blocks stolen devices.', 'All mobile subscribers and telecom consumers in India.', 'Prevents identity theft, fraud calls, and SIM-swap banking attacks.', 'Suresh checked TAFCOP and found two unknown active SIM cards registered under his Aadhaar in another state. He reported them online, leading to immediate deactivation by telecom operators.', '1. Visit Sanchar Saathi portal (sancharsaathi.gov.in).
2. Use TAFCOP module to view all mobile numbers registered with your ID.
3. Flag numbers you do not recognize as "Not My Number".
4. Use CEIR module to block IMEI of lost or stolen handsets.', 'Aadhaar number, Active registered mobile number for OTP verification, Lost phone IMEI number (if stolen).', 'Department of Telecommunications (DoT) / Telecom Service Providers', 'Sanchar Saathi Portal (sancharsaathi.gov.in)', '1. Check numbers on TAFCOP. 2. Flag unauthorized SIMs. 3. Telecom operator verification. 4. Permanent disconnection.', 'https://sancharsaathi.gov.in', 'Department of Telecommunications, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(805, 8, 'Protection Against Harassment by Illegal Digital Lending Apps', 'illegal-loan-app-harassment-protection', 'Borrowers are legally protected from aggressive recovery tactics, contact list hacking, and morphed photo extortion by digital loan apps.', 'Online loan apps cannot access your phone gallery or contacts, cannot call your relatives, and cannot harass you with abusive messages.', 'RBI Digital Lending Guidelines 2022 prohibit lending apps from accessing mobile storage, contact lists, or media. Loan recovery must follow Fair Practices Code; harassment is a punishable crime.', 'All borrowers and smartphone users targeted by unregulated instant loan apps.', 'Protects privacy, reputation, and mental health against predatory digital extortion.', 'Ramesh was harassed by an unregistered loan app calling friends from his contact list. Lodging a complaint on cybercrime.gov.in and RBI Sachet portal resulted in the app developer being booked and calls ceasing.', '1. Do not pay extortion demands under duress.
2. File a complaint on cybercrime.gov.in under financial fraud and extortion.
3. Report the app on RBI Sachet portal (sachet.rbi.org.in).
4. Lodge police complaint for extortion under Section 384 IPC / BNS.', 'Screenshots of abusive chats and call recordings, App transaction details, Bank account statements.', 'Cyber Police / Reserve Bank of India (RBI)', 'RBI Sachet Portal (sachet.rbi.org.in)', '1. File cyber police report. 2. Report on Sachet. 3. Bank accounts of fraudulent lending syndicates frozen. 4. App taken down from store.', 'https://sachet.rbi.org.in', 'Reserve Bank of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(901, 9, 'Right to Information from Public Authorities Within 30 Days (RTI)', 'right-to-information-rti-30-days', 'Citizens have the statutory right to request and inspect government files, tender records, and scheme expenditures within 30 days.', 'Under the RTI Act, any citizen can ask government departments questions about delayed projects, road repairs, or fund utilization. The department must answer in 30 days (48 hours for life/liberty).', 'Sections 6 and 7 of the Right to Information Act, 2005 mandate timely disposal of citizen queries. Failure attracts penalty of Rs. 250/day up to Rs. 25,000 on the Public Information Officer.', 'All Indian citizens seeking public accountability and government transparency.', 'Enforces democratic transparency and participatory governance.', 'Residents filed an RTI asking why a sanctioned 2-km link road was unpaved for 18 months. The municipality responded with tender timelines and initiated road paving within 3 weeks.', '1. Draft specific, clear questions on facts/records (not opinions or advice).
2. File online via rtionline.gov.in or submit physical application to Central/State PIO.
3. Pay statutory fee of Rs. 10 (free for BPL citizens).
4. If no reply in 30 days, file First Appeal within 30 days.', 'RTI application form, Identity proof (BPL card if fee exempt), Rs. 10 fee receipt / IPO.', 'Public Information Officer (PIO) / Central Information Commission (CIC)', 'RTI Online Portal (rtionline.gov.in)', '1. Submit RTI. 2. PIO response in 30 days. 3. If dissatisfied, First Appeal to FAA. 4. Second Appeal to Information Commission.', 'https://rtionline.gov.in', 'Department of Personnel and Training (DoPT), Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(902, 9, 'Right to Guaranteed Time-Bound Delivery of Public Services', 'guaranteed-time-bound-public-services', 'Citizens are entitled to guaranteed timelines for caste, income, domicile certificates, electricity meters, and building approvals.', 'State Public Service Guarantee Acts mandate that local officials must issue certificates or licenses within set days. If delayed, you can claim compensation from the defaulting official.', 'State Right to Public Services Legislation (e.g. Sakala in Karnataka, RTS in Maharashtra, e-District) prescribes maximum statutory delivery times and automatic penalties for delinquent officers.', 'All citizens applying for state certificates, revenue extracts, utility connections, and civic licenses.', 'Eliminates bureaucratic delays and reduces petty bribery.', 'Sanjay applied for a caste certificate with a 15-day statutory SLA. When delayed on Day 18, an appeal under the RTS Act compelled issuance in 24 hours and a notice to the tehsildar.', '1. Apply through state online service portal (e-District / MeeSeva / Seva Sindhu).
2. Note down the unique Application Acknowledgment Number and SLA due date.
3. If SLA breached, file First Appeal before the designated Appellate Authority.
4. Second Appeal can award compensation up to Rs. 5,000 deducted from officer salary.', 'Application acknowledgment receipt, Identity proof, Address proof, Required domain-specific supporting documents.', 'Designated Public Service Officer / District Collector', 'State Citizen Service Portal (e-District / ServicePlus)', '1. Submit application. 2. SLA countdown. 3. If breached, auto-escalation or First Appeal. 4. Guaranteed delivery with compensation.', 'https://serviceonline.gov.in', 'National Informatics Centre / Ministry of Electronics & IT', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(903, 9, 'Right to Grievance Redressal via CPGRAMS Portal', 'cpgrams-central-public-grievance-redressal', 'Citizens have the right to lodge and track grievances against central and state ministries on CPGRAMS with mandatory 30-day resolution.', 'If a bank, railway, post office, or central ministry ignores your problem, you can lodge a grievance directly on CPGRAMS. It is tracked by top authorities with a 30-day resolution mandate.', 'Centralized Public Grievance Redress and Monitoring System (CPGRAMS) operated by DARPG provides single-window redressal across 80+ central ministries with appeal facility to an independent Nodal Officer.', 'All citizens facing service deficiency from central and participating state government departments.', 'Provides direct executive oversight on citizen complaints.', 'A pensioner pension was blocked due to an inter-bank clerical mismatch for 5 months. Within 12 days of filing a CPGRAMS grievance, the Pension Department credited all arrears.', '1. Register on CPGRAMS portal (pgportal.gov.in) using mobile number.
2. Select relevant Ministry, Department, and sub-category.
3. Provide concise summary of grievance and upload previous correspondence.
4. If unsatisfied with resolution, file an Appeal within 30 days.', 'Previous complaint reference numbers, Government department communication, Identity proof, Supporting evidence.', 'Department of Administrative Reforms and Public Grievances (DARPG)', 'CPGRAMS Portal (pgportal.gov.in)', '1. File grievance. 2. Assigned to ministry nodal officer. 3. Action taken report in 30 days. 4. Feedback rating and appeal option.', 'https://pgportal.gov.in', 'DARPG, Ministry of Personnel, Public Grievances & Pensions', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(904, 9, 'Right to Biometric Lock & Demographic Correction in Aadhaar', 'aadhaar-biometric-lock-and-demographic-correction', 'Aadhaar holders have the statutory right to lock biometrics to prevent cloning and correct demographic errors online.', 'You can lock your fingerprint and iris authentication on the mAadhaar app so no one can misuse your Aadhaar for bank debits or SIM issuance. You can unlock it instantly when needed.', 'Under the Aadhaar (Targeted Delivery of Financial and Other Subsidies) Act 2016 and UIDAI regulations, citizens have full control to lock/unlock biometrics and update demographic data with documentary proof.', 'All 1.4+ billion Indian residents holding a 12-digit Aadhaar number.', 'Protects identity security and biometric integrity against AePS fraud.', 'Anita locked her biometrics on mAadhaar after hearing of AePS fraud in her town. When an attempted unauthorized biometric withdrawal was made at a CSP, it was automatically declined.', '1. Download official mAadhaar app or visit myaadhaar.uidai.gov.in.
2. Login with Aadhaar and OTP.
3. Select "Lock/Unlock Biometrics" and enable lock.
4. Temporarily unlock for 10 minutes when giving biometrics for exams or bank visits.', 'Aadhaar number, Registered mobile number active for OTP verification.', 'Unique Identification Authority of India (UIDAI)', 'myAadhaar Portal (myaadhaar.uidai.gov.in) / Helpline 1947', '1. Login to myAadhaar. 2. Enable biometric lock. 3. Real-time protection. 4. File UIDAI grievance via 1947 if needed.', 'https://uidai.gov.in', 'UIDAI, Ministry of Electronics and Information Technology', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(905, 9, 'Right to Timely Passport Issuance and Grievance Redressal', 'passport-issuance-and-grievance-redressal', 'Citizens have the statutory right to travel abroad and receive passport services in transparent, time-bound manner under the Passports Act.', 'Every Indian citizen has the fundamental right to hold an Indian passport. The government cannot refuse or delay your passport without specific statutory grounds in writing.', 'Under the Passports Act, 1967 and Supreme Court in Maneka Gandhi v. Union of India, right to travel abroad is part of Article 21 personal liberty. Passports can only be refused for grounds enumerated in Section 6.', 'All eligible Indian citizens applying for fresh passports, renewals, or Tatkaal services.', 'Protects international mobility and personal liberty under Article 21.', 'A student passport was stalled due to an erroneous adverse police report over a closed non-cognizable neighborhood dispute. Representation to the Regional Passport Officer (RPO) resulted in clearance.', '1. Submit application on passportindia.gov.in.
2. Attend biometric appointment at Passport Seva Kendra (PSK).
3. Track police verification report online.
4. If stalled, book Passport Adalat appointment or appeal to Regional Passport Officer under Sec 11.', 'Proof of date of birth (Birth Certificate / 10th marksheet), Proof of address (Aadhaar / Voter ID), Photo ID, Police verification clearance.', 'Regional Passport Office (RPO) / Ministry of External Affairs', 'Passport Seva Portal (passportindia.gov.in)', '1. Online PSK appointment. 2. Police verification within 21 days. 3. Dispatch via Speed Post. 4. Appeal to Chief Passport Officer if refused.', 'https://www.passportindia.gov.in', 'Ministry of External Affairs, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1001, 10, 'Right to Free Legal Representation for Weaker Sections', 'right-to-free-legal-aid-weaker-sections', 'Eligible citizens are entitled to free legal counsel, court fee waivers, and representation in all judicial proceedings.', 'If you cannot afford a private lawyer or belong to eligible categories like women, children, SC/ST, or low-income groups, government provides a qualified lawyer free of charge.', 'Under Article 39A of the Constitution and Section 12 of Legal Services Authorities Act, 1987, NALSA and DLSAs provide end-to-end legal representation and court fee coverage.', 'Women, children, SC/ST members, disabled persons, industrial workmen, and citizens with annual income below prescribed thresholds (typically Rs. 3 Lakhs).', 'Guarantees equal access to justice regardless of economic hardship.', 'Sunita, facing illegal eviction by landlord, approached DLSA. DLSA assigned a panel advocate free of cost who obtained a stay order protecting her occupancy.', '1. Visit the nearest District Legal Services Authority (DLSA) in District Court.
2. Or apply online via nalsa.gov.in.
3. Submit income declaration and identity proof.
4. Meet assigned panel advocate and hand over dispute documents.', 'Identity proof (Aadhaar / Voter ID), Income certificate or self-declaration, Caste/category certificate (if applicable), Case notices.', 'National Legal Services Authority (NALSA) / DLSA', 'NALSA Free Legal Aid Portal (nalsa.gov.in)', '1. Application submission. 2. Front office scrutiny in 48 hours. 3. Advocate assigned from panel. 4. Representation in court.', 'https://nalsa.gov.in', 'Supreme Court of India / NALSA', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1002, 10, 'Settlement of Disputes Through National Lok Adalat', 'dispute-settlement-national-lok-adalat', 'Citizens can resolve pending civil, matrimonial, bank loan, and motor accident disputes amicably in Lok Adalat with full refund of court fees.', 'Lok Adalats offer fast, compromise-based settlements with zero court fees. If you settle a pending court case in Lok Adalat, you get 100% of your paid court fees refunded, and no appeal lies against the award.', 'Sections 19, 20, and 21 of the Legal Services Authorities Act, 1987 give Lok Adalat awards the status of a final civil court decree. Court fees paid in the court are refunded under Section 16 of the Court Fees Act.', 'All parties involved in compoundable criminal, civil, motor accident, matrimonial, or financial recovery disputes.', 'Delivers finality without appeals, saves decades of litigation costs.', 'A 4-year-old motor accident claim was referred to National Lok Adalat. The insurance company and victim agreed on Rs. 8.5L compensation in a single day, and full court fees were refunded.', '1. Apply to the presiding judge of your court to refer case to upcoming Lok Adalat.
2. Or approach DLSA for Pre-Litigation Lok Adalat reference before filing formal suit.
3. Attend conciliation sitting with panel members (retired judge + advocate).
4. Sign joint compromise settlement; award is final and non-appealable.', 'Case number and petition copy, Compromise terms draft, ID proofs, Court fee deposit receipt.', 'National Legal Services Authority (NALSA) / State Legal Services Authority (SLSA)', 'NALSA National Lok Adalat Schedule', '1. Referral to Lok Adalat. 2. Pre-counseling sitting. 3. Joint settlement signed. 4. Award passed and court fee refund certificate issued.', 'https://nalsa.gov.in', 'Supreme Court of India / NALSA', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1003, 10, 'Pre-Litigation Mediation Under the Mediation Act, 2023', 'pre-litigation-mediation-act-2023', 'Parties in civil and commercial disputes have the right to resolve conflicts confidentially through accredited mediators before going to court.', 'Instead of fighting in court for years, you can sit with a trained neutral mediator to work out a mutually acceptable settlement. The signed mediated agreement has the same legal value as a court judgment.', 'The Mediation Act, 2023 formalizes pre-litigation mediation. A Mediated Settlement Agreement is enforceable in the same manner as a judgment or decree passed by a court under CPC.', 'Parties to commercial, property, family, partnership, and civil disputes.', 'Preserves relationships, ensures confidentiality, and dramatically lowers dispute costs.', 'Two business partners disputing asset division entered pre-litigation mediation. Over 4 sessions, the mediator helped them structure an asset buyout, registered as an enforceable decree in 20 days.', '1. Approach a court-annexed Mediation Centre or recognized Mediation Service Provider.
2. Serve mediation notice to the opposite party.
3. Attend confidential joint and separate caucus sessions with the mediator.
4. Execute Mediated Settlement Agreement and register it with the Authority.', 'Dispute summary statement, Relevant contracts/agreements, Identity proofs, Draft terms of settlement.', 'Mediation and Conciliation Project Committee (Supreme Court) / District Court Mediation Centre', 'Mediation Council of India Portal', '1. Mediation notice. 2. Mediator appointment. 3. Maximum 120-day mediation process. 4. Enforceable settlement agreement executed.', 'https://www.indiacode.nic.in/handle/123456789/19324', 'Ministry of Law and Justice, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1004, 10, 'Right to Free Certified Copies of Court Orders for Indigent Litigants', 'free-certified-copies-court-orders', 'Litigants belonging to indigent categories or represented by legal aid have the right to free certified copies of judgments and trial orders.', 'If you are represented by legal aid or in custody, the court must give you certified copies of bail orders, chargesheets, and judgments free of charge.', 'Under High Court Rules and Section 363 CrPC (Sec 404 BNSS), an accused person sentenced to imprisonment or a legal-aid litigant is entitled to a free certified copy of judgment immediately upon pronouncement.', 'All indigent litigants, prisoners, undertrials, and parties represented by DLSA/HCLSC.', 'Guarantees fair appeal opportunities and prevents incarceration without judicial record.', 'An undertrial in judicial custody was granted bail but could not afford certified copy copying fees. Legal aid counsel applied under Section 363 CrPC and obtained the certified order free, releasing him.', '1. File an urgent application for certified copy marked "Through Legal Aid / In Custody".
2. Cite Section 363 CrPC / Sec 404 BNSS and DLSA representation.
3. Copying agency must deliver certified copy on prioritized basis without charging court fee stamps.
4. Furnish copy to Jail Superintendent for bail release.', 'Case number / Court room details, DLSA allotment letter, Undertrial custody certificate.', 'Court Copying Agency / District Legal Services Authority', 'eCourts Portal (ecourts.gov.in)', '1. File free copy application. 2. Judicial officer endorsement. 3. Prioritized copying. 4. Certified delivery to litigant/jail.', 'https://ecourts.gov.in', 'e-Committee, Supreme Court of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1005, 10, 'Right to State-Appointed Defense Counsel in Criminal Trials', 'state-appointed-defense-counsel-criminal-trial', 'Every accused person unable to afford an advocate is entitled to a qualified defense counsel appointed and paid by the state.', 'If you are arrested and cannot pay for a lawyer, the Magistrate or Sessions Court must assign a qualified advocate to defend you at state expense.', 'Article 22(1) and Article 39A of Constitution, read with Section 304 CrPC (Sec 340 BNSS) and landmark Supreme Court ruling in Khatri v. State of Bihar, make legal representation an inalienable right from the moment of arrest.', 'All accused persons facing criminal prosecution who lack financial means to engage private counsel.', 'Prevents unfair convictions and protects liberty against arbitrary state power.', 'A daily wage worker was falsely implicated in a theft case and produced before the Magistrate. The Magistrate noted he had no counsel and immediately assigned a DLSA panel advocate, who secured bail in the first remand hearing.', '1. Inform the Remand Magistrate immediately that you cannot afford a private lawyer.
2. Magistrate has a constitutional duty to assign a DLSA Remand Advocate.
3. Request interaction with legal-aid counsel before remand order is signed.
4. Counsel files bail application and defends trial free of cost.', 'Identity proof (if available), Remand paper copy, DLSA appointment form.', 'Judicial Magistrate / Sessions Court / DLSA Legal Aid Defense Counsel System (LADCS)', 'NALSA LADCS Wing', '1. Production before Magistrate. 2. Legal aid inquiry by Bench. 3. LADCS advocate assigned on spot. 4. Defense representation throughout trial.', 'https://nalsa.gov.in', 'Supreme Court of India / NALSA', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1101, 11, 'Right to Claim Monthly Maintenance from Adult Children', 'senior-citizen-monthly-maintenance-claim', 'Senior citizens unable to maintain themselves have the enforceable legal right to claim maintenance from adult children or heirs.', 'If your children or grandchildren neglect you and you have no income, you can file a simple petition before the Sub-Divisional Magistrate (SDM). The SDM can order monthly maintenance directly credited to your account.', 'Under the Maintenance and Welfare of Parents and Senior Citizens Act 2007 (Sections 4 & 5), parents and senior citizens can claim monthly allowance. Proceedings are summary and must be disposed within 90 days.', 'Any Indian citizen aged 60+ or parents (even if below 60) unable to maintain themselves.', 'Guarantees dignity, food, clothing, shelter, and medical care in old age.', '70-year-old widow Savitri was abandoned by two well-earning sons. She approached the SDM Maintenance Tribunal. The Tribunal ordered each son to pay Rs. 6,000 monthly maintenance deducted from salary.', '1. Approach the SDM (Maintenance Tribunal) in your district/sub-division.
2. Call Elder Line 14567 for free help with drafting the application.
3. File application under Section 5 of the Act.
4. No advocate is required; no court fee is payable.', 'Age proof (Aadhaar / Voter ID / Pension Card), Proof of relationship with children, Bank account details, Medical prescription/bills.', 'Maintenance Tribunal (Sub-Divisional Magistrate Office)', 'Elder Line (14567) / Senior Citizen Welfare Portal', '1. Application to SDM. 2. Notice to children. 3. Conciliation attempt. 4. Order passed within 90 days. 5. Direct bank attachment if children default.', 'https://elderline.dosje.gov.in', 'Ministry of Social Justice and Empowerment, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1102, 11, 'Right to Cancel Property Transfers & Gift Deeds if Neglected', 'senior-citizen-property-transfer-cancellation', 'Senior citizens can get property gift deeds or transfers declared void by the SDM if children fail to provide basic amenities.', 'If you gifted your house or land to your child on the promise of care, and they later mistreat or neglect you, the SDM can cancel the transfer and return ownership to you.', 'Section 23 of the Maintenance and Welfare of Parents and Senior Citizens Act 2007 provides that property transfers made on condition of maintenance become void at the option of the senior citizen if neglected.', 'Senior citizens (60+) who transferred property after the enactment of the 2007 Act.', 'Prevents property grabbing by ungrateful relatives and protects elder shelter.', '76-year-old Mohanlal gifted his ancestral home to his son. The son later attempted to evict Mohanlal. The SDM Maintenance Tribunal declared the gift deed void and restored the mutation in Mohanlal name.', '1. Obtain a certified copy of the registered Gift Deed or Settlement Deed.
2. File an application under Section 23 of MWPSC Act before the SDM.
3. Demonstrate failure of children to provide basic physical amenities and care.
4. SDM issues order declaring the transfer deed void and cancels registration.', 'Copy of registered Gift/Transfer deed, Aadhaar/Age proof, Evidence of neglect (medical bills, police complaints, witness statements).', 'Maintenance Tribunal (SDM) / Sub-Registrar Office', 'Elder Line (14567)', '1. Section 23 petition. 2. Summary hearing. 3. Tribunal order declaring deed void. 4. Sub-Registrar cancels deed and updates land records.', 'https://elderline.dosje.gov.in', 'Ministry of Social Justice and Empowerment, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1103, 11, 'Right to Dedicated Geriatric Healthcare & Priority in Hospitals', 'senior-citizen-geriatric-healthcare-priority', 'Senior citizens are entitled to separate queues, dedicated geriatric beds, and subsidized treatment in government and empaneled hospitals.', 'You do not have to wait in long hospital lines. Government hospitals and dispensaries must provide separate registration and pharmacy queues, and dedicated elder healthcare.', 'Section 20 of the MWPSC Act 2007 and National Programme for Health Care of the Elderly (NPHCE) mandate separate queues, geriatric OPDs, and priority beds for senior citizens across health facilities.', 'All senior citizens aged 60 and above seeking medical care in India.', 'Ensures prompt medical attention and compassionate care for fragile elders.', 'An 82-year-old pensioner faced 3-hour waits at a civil hospital OPD. Presenting his Senior Citizen card at the hospital administration secured immediate dedicated elder queue routing and geriatric medication.', '1. Show Senior Citizen ID card or Aadhaar showing age 60+ at the hospital reception.
2. Request routing to the dedicated Senior Citizen OPD / Geriatric Counter.
3. Beneficiaries under Ayushman Bharat (PM-JAY) above 70 receive Rs. 5 Lakhs annual free healthcare.
4. Lodge complaint with Chief Medical Officer if separate facilities denied.', 'Aadhaar / Senior Citizen ID card, Ayushman Bharat Vay Vandana Card (for 70+), Medical prescription records.', 'District Hospital / Chief Medical Officer / NPHCE', 'Ayushman Bharat PM-JAY Portal (pmjay.gov.in)', '1. Show age proof. 2. Direct priority registration. 3. Geriatric consultation. 4. Free medicines and priority diagnostic tests.', 'https://main.mohfw.gov.in', 'Ministry of Health and Family Welfare, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1104, 11, 'Protection Against Eviction from Self-Acquired Property', 'senior-citizen-protection-from-eviction', 'Senior citizens have the absolute legal right to live peacefully in their self-acquired homes without harassment or forceful eviction by adult children.', 'Your adult children or relatives have no automatic right to live in your self-acquired house if they harass you. You can obtain a court order evicting abusive children from your premises.', 'Supreme Court in Smt. S. Vanitha v. Deputy Commissioner and High Court rulings under the Senior Citizens Act have established that senior citizens can seek eviction of abusive adult children from self-acquired homes.', 'Senior citizens who own or hold legal possession of residential properties.', 'Guarantees peace of mind and physical safety in one own home.', 'A retired teacher was abused by his adult son who demanded an immediate property sale. The Maintenance Tribunal ordered police-assisted eviction of the son, securing the elder residence.', '1. Serve a written legal notice to the abusive child directing them to vacate.
2. File an application under Section 4/22 of the MWPSC Act before the District Magistrate/SDM.
3. Point out mental harassment and property ownership.
4. DM passes eviction order enforced by local police.', 'Property title deed / Allotment letter, Aadhaar / Age proof, Police complaints or diary entries detailing abuse.', 'District Magistrate / Maintenance Tribunal / Local Police', 'District Magistrate Grievance Cell', '1. Eviction petition filed. 2. Summary inquiry. 3. Eviction order passed. 4. Local police ensures vacating within 30 days.', 'https://elderline.dosje.gov.in', 'Ministry of Social Justice and Empowerment, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1105, 11, 'Access to National Elder Helpline 14567 for Abuse Intervention', 'national-elder-helpline-14567-intervention', 'Elderly victims of abandonment, abuse, or isolation have access to 24x7 toll-free helpline 14567 for field rescue, counseling, and shelter.', 'If you or an elderly neighbor is abandoned, starving, or physically abused, dialing 14567 immediately mobilizes local field response officers, police, and old age shelter support.', 'Elder Line (14567) is the National Helpline for Senior Citizens operated by the Ministry of Social Justice and Empowerment across all states, coordinating with DMs, police, and old-age homes.', 'Any senior citizen facing abuse, homelessness, emotional distress, or legal abandonment.', 'Provides immediate emergency rescue and rehabilitation.', 'An 80-year-old man was abandoned at a bus station by relatives. A bystander called 14567. The Elder Line field response team arrived within 2 hours, provided medical care, and placed him in an accredited shelter.', '1. Dial toll-free number 14567 from any mobile or landline phone.
2. Explain the situation: address, nature of abuse/abandonment, immediate medical needs.
3. Elder Line Field Response Officer (FRO) visits the location.
4. Facilitates rescue, shelter admission, or legal representation before the SDM.', 'Any available photo ID (if available), Location details, Medical reports (if hospitalized).', 'Ministry of Social Justice and Empowerment / State Social Welfare Department', 'Elder Line 14567 / National Portal for Senior Citizens', '1. Call 14567. 2. Triage and dispatch. 3. On-ground field intervention. 4. Rescue to shelter home and legal action on negligent heirs.', 'https://elderline.dosje.gov.in', 'Ministry of Social Justice and Empowerment, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1201, 12, 'Mandatory Reporting & Special Court Trial in Child Sexual Abuse (POCSO)', 'pocso-act-mandatory-reporting-and-protection', 'Children are protected from sexual offenses with mandatory reporting, in-camera child-friendly trials, and non-disclosure of victim identity.', 'Under the POCSO Act, any sexual abuse of a child below 18 is severely punished. The child never has to face the accused in court, and the media cannot reveal the child identity.', 'The Protection of Children from Sexual Offences (POCSO) Act, 2012 provides child-friendly investigation, recording statements at the child residence, mandatory interim compensation, and special fast-track courts.', 'All children below 18 years of age regardless of gender.', 'Protects child dignity and bodily integrity from predatory abuse.', 'A school teacher sexually harassed a 12-year-old student. The principal reported it under Section 19 POCSO. A Special Fast Track Court convicted the accused and awarded Rs. 4 Lakhs interim victim compensation.', '1. Report immediately to local police, Special Juvenile Police Unit (SJPU), or Childline 1098.
2. Police must register FIR under POCSO immediately.
3. Statement recorded by woman magistrate under Sec 164 in child-friendly setting without uniform.
4. Special Court completes trial within 1 year.', 'Child birth certificate, Medical examination report, Written complaint by parent/guardian, Any electronic evidence.', 'Special Juvenile Police Unit (SJPU) / Special POCSO Court / Child Welfare Committee', 'Childline 1098 / National Commission for Protection of Child Rights (NCPCR)', '1. FIR under POCSO. 2. Medical care & counseling. 3. Statement under 164 CrPC. 4. Special POCSO Court trial completed within 1 year.', 'https://www.indiacode.nic.in/handle/123456789/2079', 'Ministry of Women and Child Development, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1202, 12, 'Total Ban on Child Labour Below 14 & Hazardous Employment up to 18', 'child-labour-prohibition-act-pencil-portal', 'Employment of children below 14 in any commercial establishment is strictly prohibited, with rescue and rehabilitation mandated under law.', 'No child under 14 years can be employed in any shop, restaurant, factory, or home business. Adolescents (14-18) cannot be employed in hazardous industries.', 'Child and Adolescent Labour (Prohibition and Regulation) Act 1986 completely bans child labour below 14. Employing children is a cognizable criminal offense punishable with up to 2 years imprisonment.', 'All children below 14 years, and adolescents aged 14 to 18 in hazardous industries.', 'Guarantees freedom to study and protects childhood development under Article 24.', 'A raid by Labour Department and Childline rescued six 11-year-old boys working in a brick kiln. The employer was booked, and children were enrolled in residential schooling with Rs. 30,000 rehabilitation deposit each.', '1. Report child labour on PENCiL portal (pencil.gov.in) or call Childline 1098.
2. District Task Force conducts rescue operation.
3. Rescued child is produced before Child Welfare Committee (CWC).
4. Offending employer is booked, and child is enrolled in government school under RTE.', 'Rescue report by Task Force, Age verification by Medical Board, CWC rehabilitation order.', 'District Child Labour Task Force / Labour Department / CWC', 'PENCiL Portal (pencil.gov.in) / Childline 1098', '1. Complaint on PENCiL. 2. Rescue raid. 3. Medical examination. 4. School enrollment and employer prosecution.', 'https://pencil.gov.in', 'Ministry of Labour and Employment, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1203, 12, 'Child Welfare Committee (CWC) Powers for Children in Need of Care', 'cwc-powers-children-in-need-of-care', 'Orphaned, abandoned, or abused children have the statutory right to care, protection, foster families, and state shelter under the CWC.', 'The Child Welfare Committee (CWC) functions like a family court for children who are lost, abandoned, or abused. CWC ensures safe shelter, schooling, and legal guardianship.', 'Under Juvenile Justice (Care and Protection of Children) Act 2015 Sections 27-38, the CWC has the powers of a Judicial Magistrate to make decisions regarding care, rehabilitation, and legal adoption of children in need.', 'Any child below 18 years found abandoned, orphaned, trafficked, or living on the street.', 'Prevents child exploitation and institutionalizes state guardianship.', 'A 7-year-old run-away child was found at a railway platform. GRP produced him before CWC. CWC traced his parents via TrackChild portal and safely reunited him within 48 hours.', '1. Anyone finding an abandoned or distressed child must produce them before CWC or call 1098.
2. CWC conducts inquiry into the background and needs of the child.
3. Issues orders for institutional care, foster care, or family reunification.
4. If parents cannot be traced, declares child legally free for adoption.', 'CWC Production form, Social Investigation Report (SIR), Medical examination report, TrackChild registration slip.', 'Child Welfare Committee (CWC) / District Child Protection Unit (DCPU)', 'TrackChild Portal / Mission Vatsalya (wcd.nic.in)', '1. Child produced before CWC. 2. SIR inquiry by Child Welfare Officer. 3. Safe shelter order. 4. Reunification or foster care.', 'https://www.indiacode.nic.in/handle/123456789/2144', 'Ministry of Women and Child Development, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1204, 12, 'Right of Every Child to Free Birth Registration Within 21 Days', 'right-to-free-birth-registration-21-days', 'Every child born in India has the statutory fundamental right to free birth registration and issuance of Birth Certificate within 21 days.', 'A birth certificate is a child first legal right and proof of citizenship. Hospitals and local municipal bodies must register birth and provide the first certificate free of cost within 21 days.', 'Under Registration of Births and Deaths Act 1969 Section 8 and RBD Amendment Act 2023, birth registration is mandatory and serves as universal proof of identity, school admission, and passport issuance.', 'Every newborn infant born in institutional or home settings in India.', 'Prevents statelessness and guarantees legal personhood and identity.', 'A rural clinic delayed birth paperwork for 6 months. Representation to the Chief Registrar of Births citing Section 8 RBD Act secured issuance within 3 days without late fees.', '1. Ensure hospital or birth attendant completes birth reporting form (Form 1).
2. Register birth with local Gram Panchayat / Municipal Corporation within 21 days (zero fee).
3. If delayed up to 30 days, pay small late fee; if delayed over 1 year, SDM order required.
4. Download digital QR-code verified Birth Certificate online from crsorgi.gov.in.', 'Hospital birth discharge summary, Parents Aadhaar cards, Marriage certificate (if available), Form 1 application.', 'Registrar of Births and Deaths (Municipality / Gram Panchayat)', 'Civil Registration System Portal (crsorgi.gov.in)', '1. Form 1 submission. 2. Verification. 3. Entry in Birth Register. 4. Issuance of digitally signed Birth Certificate.', 'https://crsorgi.gov.in', 'Office of the Registrar General of India, Ministry of Home Affairs', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1205, 12, 'Emergency Rescue and Support via 24x7 Childline 1098', 'emergency-childline-1098-rescue-support', 'Any child in distress or citizen reporting child abuse has the right to emergency response, rescue, and medical aid via toll-free helpline 1098.', 'Childline 1098 is a 24-hour free emergency phone service for children in need of aid and assistance. Calls connect directly to child protection officers who intervene on the ground.', 'Childline is integrated under Mission Vatsalya and the Juvenile Justice Act 2015, linking emergency calls to police, child welfare committees, hospitals, and child care institutions.', 'Any child below 18 years experiencing physical violence, trafficking, child marriage, or hunger.', 'Provides an accessible emergency lifeline for vulnerable children.', 'A neighbor reported a 13-year-old girl being coerced into child marriage. Childline 1098 alerted the District Child Protection Officer and police, stopping the marriage and providing CWC counseling.', '1. Dial 1098 from any phone (toll-free, no balance needed).
2. Provide specific location and nature of emergency (abuse, child marriage, trafficking).
3. Childline team coordinates with local police and reaches within 60 minutes.
4. Child is escorted to safety and produced before CWC.', 'Location landmarks, Details of abusers/guardians, Any visible injury photos or recordings.', 'Mission Vatsalya Childline Unit / Special Juvenile Police Unit', 'Childline 1098 / National Portal on Child Protection', '1. Dial 1098. 2. Emergency dispatch. 3. Physical on-ground rescue. 4. Medical attention and CWC protection orders.', 'https://wcd.nic.in', 'Ministry of Women and Child Development, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1301, 13, 'Equal Opportunity & 4% Government Employment Reservation', 'disability-equal-opportunity-employment-reservation', 'Persons with benchmark disabilities are entitled to 4% reservation in government vacancies and non-discrimination in private employment.', 'Under the RPwD Act, 4% of all government job vacancies are reserved for persons with disabilities. Employers cannot deny promotion or terminate you if you acquire a disability during service.', 'Sections 3, 20, and 34 of the Rights of Persons with Disabilities Act, 2016 mandate 4% reservation in public establishments and require every establishment to notify an Equal Opportunity Policy.', 'Persons with benchmark disabilities (at least 40% specified disability).', 'Ensures economic empowerment and self-reliance under Article 14 & 16.', 'A bank employee lost eyesight in an accident and was served a premature retirement notice. Citing Section 20 of RPwD Act, the court ordered the bank to retain him on an alternative desk with full pay.', '1. Obtain a valid Unique Disability ID (UDID) Card with 40%+ benchmark assessment.
2. Apply under reserved PwD category in central/state recruitment.
3. Request reasonable accommodations and scribe facilities during selection exams.
4. If discriminated in promotion or service, petition the State Commissioner for Persons with Disabilities.', 'UDID Card / Disability Certificate from Medical Board, Recruitment application copy, Medical fitness certificate.', 'State Commissioner for Persons with Disabilities / Ministry of Social Justice', 'Swavlamban Portal (swavlambancard.gov.in)', '1. UDID verification. 2. Application in 4% quota. 3. Reasonable accommodations provided. 4. Equal opportunity grievance cell.', 'https://www.indiacode.nic.in/handle/123456789/2155', 'Department of Empowerment of Persons with Disabilities', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1302, 13, 'Right to Built-Environment Accessibility in Public Places & Transport', 'mandatory-accessibility-public-buildings-transport', 'All public buildings, railway stations, airports, buses, and public websites must adhere to mandatory accessibility standards.', 'Government offices, banks, malls, and public transport must have ramps, tactile paths, accessible toilets, and Braille signage so persons with disabilities can move freely.', 'Sections 40-46 of RPwD Act 2016 and Harmonised Guidelines mandate universal accessibility. Failure to provide accessibility in buildings and transport is a statutory violation.', 'All persons with locomotor, visual, hearing, or neurological disabilities.', 'Guarantees freedom of movement and dignity under Article 19 & 21.', 'A wheelchair user could not enter a nationalized bank due to steep stairs without a ramp. A complaint to the Commissioner for Persons with Disabilities compelled the bank to build a ramp and tactile paving.', '1. Take photos of inaccessible public premises, lack of ramps, or broken lifts.
2. Submit written grievance to the building administrator or Chief Engineer.
3. Lodge formal complaint with the State Commissioner for Persons with Disabilities.
4. Commissioner issues summons and directs structural compliance within 60 days.', 'Photographs of inaccessible premises, Location details, Disability certificate / UDID Card.', 'Chief Commissioner / State Commissioner for Persons with Disabilities', 'Accessible India Campaign (Sugamya Bharat Abhiyan)', '1. Complaint to Commissioner. 2. Notice to authority. 3. Accessibility audit. 4. Direction to construct ramps/lifts.', 'https://disabilityaffairs.gov.in', 'Ministry of Social Justice and Empowerment, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1303, 13, 'Right to 5% Reservation & Inclusive Education in Higher Studies', 'disability-5-percent-higher-education-reservation', 'Students with benchmark disabilities are entitled to 5% reservation in all government and aided higher educational institutions.', 'Colleges and universities must reserve 5% of admission seats for students with disabilities and give a 5-year upper age relaxation, along with accessible study materials and exam scribes.', 'Sections 16 and 32 of the RPwD Act, 2016 mandate inclusive education, campus accessibility, assistive devices, and minimum 5% reservation in all government institutions of higher education.', 'Students with benchmark disabilities (40%+) pursuing school, university, or professional degrees.', 'Guarantees educational equity and career advancement.', 'A visually impaired student was denied an exam scribe for university entrance. High Court intervention citing RPwD Act Section 16 ordered immediate scribe provision and 20 minutes extra time per hour.', '1. Register under PwD quota in NEET, JEE, CUET, or university admissions.
2. Request compensatory time (20 min/hour) and scribe facility well in advance.
3. Request accessible digital textbooks and assistive technology from campus Enabling Unit.
4. Approach university Ombudsperson or Disability Commissioner if denied.', 'UDID Card / Disability Certificate, Exam admit card, Scribe requirement undertaking, School/college marksheets.', 'University Enabling Unit / State Commissioner for Persons with Disabilities', 'Swavlamban Portal / UGC Guidelines on PwD Students', '1. Apply in 5% quota. 2. Scribe allotment. 3. Compensatory exam time. 4. Campus accessibility support.', 'https://www.ugc.gov.in', 'University Grants Commission / DEPwD', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1304, 13, 'Right to Unique Disability ID (UDID) Card for National Benefits', 'udid-unique-disability-id-card-rights', 'Persons with disabilities have the statutory right to a unified national UDID card accepted across all states for welfare schemes and travel concessions.', 'You do not need to carry multiple hospital disability certificates. The digital UDID card is accepted across all states for railway concessions, bus passes, pensions, and equipment aid.', 'The Swavlamban Card (UDID) project under DEPwD creates a national database and issues smart identity cards with QR-code verification, eliminating repeat medical board examinations for permanent disabilities.', 'All Indian citizens with recognized disabilities under the 21 categories of the RPwD Act.', 'Simplifies government benefit delivery and eliminates bureaucratic paperwork.', 'Ramesh had an old district hospital paper certificate that was rejected by another state railway counter. Getting his UDID card online enabled hassle-free 75% railway concession nationwide.', '1. Apply online on Swavlamban portal (swavlambancard.gov.in).
2. Upload Aadhaar, photograph, and existing disability documents.
3. Attend designated District Hospital Medical Board for physical assessment.
4. Download e-UDID card online and receive physical smart card via post.', 'Aadhaar card / Identity proof, Passport size photo, Medical reports from specialist, Previous disability certificate (if any).', 'Department of Empowerment of Persons with Disabilities / District Medical Board', 'Swavlamban Portal (swavlambancard.gov.in)', '1. Online registration. 2. Hospital medical board exam. 3. Percentage certification. 4. UDID card generated.', 'https://www.swavlambancard.gov.in', 'Department of Empowerment of Persons with Disabilities', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1305, 13, 'Grievance Redressal Before Commissioner for Persons with Disabilities', 'disability-commissioner-quasi-judicial-redressal', 'Citizens can file complaints before the Disability Commissioner, who has civil court powers to penalize violators of disability rights.', 'If any school, employer, bank, or government department denies your legal rights as a disabled person, the Disability Commissioner can summon them, examine records, and order immediate corrective action.', 'Sections 75-83 of RPwD Act 2016 empower Chief and State Commissioners with powers of a Civil Court under CPC to summon witnesses, demand documents, and recommend prosecution.', 'Any person with disability, parent, or NGO facing rights violations or discrimination.', 'Provides speedy, accessible, zero-cost quasi-judicial remedies.', 'An airline denied boarding to a passenger with cerebral palsy. The Chief Commissioner for Persons with Disabilities summoned airline directors, imposed monetary compensation, and ordered staff sensitization.', '1. Draft a simple complaint stating facts, date, and nature of discrimination.
2. Attach UDID card copy and correspondence with the violating entity.
3. Submit by post, email, or online on the State Disability Commissioner portal.
4. Commissioner issues summons to opposite party and conducts hearings.', 'Disability Certificate / UDID, Written complaint copy, Communications with violating entity, Supporting evidence/photos.', 'Court of Chief Commissioner for Persons with Disabilities / State Commissioner', 'DEPwD National Redressal Wing', '1. File complaint. 2. Commissioner issues summons. 3. Personal or virtual hearing. 4. Binding direction and compliance report.', 'https://www.ccdisabilities.nic.in', 'Office of Chief Commissioner for Persons with Disabilities', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1401, 14, 'Right to Registration of Zero FIR at Any Police Station', 'zero-fir-mandatory-registration-any-police-station', 'A victim of a cognizable offense has the absolute legal right to register an FIR at any police station regardless of jurisdiction.', 'If a crime occurs, you can walk into the nearest police station to lodge an FIR. Police cannot refuse by saying "this area is not under our police station". They must file a Zero FIR and transfer it later.', 'Supreme Court in Lalita Kumari v. Govt of UP and Section 173 of BNSS (Section 154 CrPC) mandate immediate registration of Zero FIR for all cognizable offenses. Refusal by police officer is a criminal offense under Section 166A IPC/BNS.', 'All citizens reporting cognizable offenses including robbery, sexual assault, murder, kidnapping, and accidents.', 'Prevents loss of critical evidence and eliminates territorial excuses by police.', 'A woman was assaulted on an interstate highway. The nearest town police station initially refused. After she cited the Zero FIR mandate, police registered Zero FIR No. 00/2026 and transferred it to the highway jurisdiction.', '1. Approach the nearest police station immediately.
2. State that you want to register a "Zero FIR" under Supreme Court directives.
3. Provide oral or written details of the incident.
4. Demand a free signed copy of the FIR immediately with Zero FIR number.', 'Written complaint / statement of facts, Identity proof (optional for reporting crime), Medical MLC report (if injured).', 'Station House Officer (SHO) of Any Police Station / Superintendent of Police (SP)', 'State Police Online FIR Portal / CCTNS System', '1. Report crime. 2. Police registers Zero FIR. 3. Free FIR copy handed to informant. 4. Case diary transferred to jurisdictional police.', 'https://ncrb.gov.in', 'National Crime Records Bureau (NCRB) / Ministry of Home Affairs', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1402, 14, 'Safeguards Against Arbitrary Arrest Under DK Basu Guidelines', 'dk-basu-guidelines-arrest-safeguards', 'Arrested persons have statutory rights to know grounds of arrest, inform family within 8 hours, and undergo independent medical examination.', 'Police cannot arrest you secretly. They must wear clear name tags, prepare an arrest memo signed by a witness, inform your family immediately, and take you for medical examination every 48 hours.', 'DK Basu v. State of West Bengal guidelines and Sections 41A, 50, 50A, and 54 of CrPC (Sections 35, 47, 53 BNSS) provide constitutional safeguards against custodial torture and arbitrary detention.', 'Every citizen intercepted, detained, or arrested by police or investigative agencies.', 'Protects personal liberty against custodial torture under Article 21 & 22.', 'Punit was picked up by police without explanation. His advocate cited DK Basu guidelines: failure to prepare an arrest memo and refusal to inform family resulted in the Magistrate releasing Punit on personal bond.', '1. Ask the arresting officer for their name, designation, and arrest memo.
2. Nominate a family member or friend to be formally informed of your arrest.
3. Demand medical examination to document physical condition before lockup.
4. Demand to be produced before a Judicial Magistrate within 24 hours.', 'Arrest Memo copy, Notice of appearance under Sec 41A (if bailable/under 7 years), Medical Examination Report (MLC).', 'Judicial Magistrate / District Legal Services Authority Remand Advocate', 'National Human Rights Commission (NHRC)', '1. Arrest memo signed by relative/witness. 2. Entry in police station general diary. 3. Medical examination. 4. Production before Magistrate in 24 hours.', 'https://www.indiacode.nic.in/handle/123456789/16225', 'Ministry of Home Affairs, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1403, 14, 'Right of Arrested Persons to Free Legal Consultation and Statutory Bail', 'arrested-persons-statutory-bail-and-legal-aid', 'Arrested persons have the constitutional right to consult a lawyer of choice and mandatory statutory bail if investigation is delayed.', 'You have the right to speak to a lawyer immediately upon arrest. If the offense is bailable, police must grant bail. If chargesheet is not filed within 60/90 days, you get automatic statutory bail.', 'Article 22(1) of Constitution, Section 436 CrPC (mandatory bail in bailable offenses), and Section 167(2) CrPC (default bail if chargesheet delayed past 60/90 days) guarantee fundamental liberty.', 'All accused persons undergoing investigation or custody.', 'Prevents indefinite imprisonment without charge sheet.', 'An accused remained in custody for 92 days without police filing a chargesheet in a theft case. Legal aid counsel applied under Section 167(2) CrPC, securing indefeasible default bail as a matter of right.', '1. Assert your right to consult an advocate before answering custodial interrogation.
2. If offense is bailable, demand bail at the police station by offering surety.
3. If chargesheet not filed within 60 or 90 days, file an application for Default Bail.
4. If indigent, request the Remand Magistrate to assign a DLSA panel lawyer.', 'Arrest memo, Remand orders, First Information Report (FIR) copy, Bail bond / surety papers.', 'Judicial Magistrate / Sessions Court / DLSA Legal Aid Defense Counsel System', 'eCourts Portal / NALSA Legal Aid Wing', '1. Production before Magistrate. 2. Legal aid interaction. 3. Bail hearing. 4. Execution of bail bond and release order to jail.', 'https://ecourts.gov.in', 'Supreme Court of India / NALSA', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1404, 14, 'State Victim Compensation for Serious Crime Survivors', 'state-victim-compensation-scheme-nalsa', 'Victims of rape, acid attacks, child abuse, and bodily crimes are entitled to substantial state financial compensation and free medical treatment.', 'If you or your family suffers a serious crime, the state government must pay monetary compensation (up to Rs. 10 Lakhs) for medical rehabilitation, regardless of whether the accused is caught or convicted.', 'Section 357A of CrPC (Section 396 BNSS) and NALSA Compensation Scheme for Women Victims/Survivors of Sexual Assault/Other Crimes mandate state compensation funds administered by DLSAs.', 'Victims and dependents of rape, acid attack, POCSO offenses, human trafficking, and grievous bodily harm.', 'Provides restorative justice, trauma care, and economic survival.', 'An acid attack survivor needed multiple reconstructive surgeries. DLSA awarded Rs. 7 Lakhs compensation within 15 days under the NALSA scheme, with all hospital costs covered by the state.', '1. Approach District Legal Services Authority (DLSA) in your District Court.
2. Submit an application for interim victim compensation.
3. DLSA conducts preliminary verification of FIR and medical reports.
4. Interim compensation must be disbursed within 15 days of application.', 'FIR copy, Medico-Legal Certificate (MLC) and hospital treatment bills, Identity proof, Bank account details.', 'District Legal Services Authority (DLSA) / State Victim Compensation Board', 'NALSA Victim Compensation Portal (nalsa.gov.in)', '1. Application to DLSA. 2. Scrutiny in 7 days. 3. Interim compensation awarded. 4. Final award upon trial conclusion.', 'https://nalsa.gov.in', 'Supreme Court of India / NALSA', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0),
(1405, 14, 'Witness Protection & Identity Concealment in Criminal Proceedings', 'witness-protection-scheme-identity-concealment', 'Key witnesses facing intimidation or threat have the legal right to police protection, identity concealment, and relocation under Witness Protection Scheme.', 'If an accused or powerful person threatens you because you witnessed a crime, court and police must provide armed protection, conceal your name in records, or relocate your family.', 'Supreme Court in Mahender Chawla v. Union of India (2018) approved the Witness Protection Scheme, making it the law of the land under Article 141. Competent Authorities assess threat perception.', 'Witnesses, victims, and their family members facing threats in serious criminal trials.', 'Prevents witness hostility and preserves the integrity of criminal justice.', 'An eyewitness in a gang robbery case received threats. The Competent Authority approved Witness Protection: police escorts during hearings, identity mask in court, and home patrolling were provided.', '1. File an application in the prescribed format before the Standing Committee / District Judge.
2. Threat Analysis Report is prepared by the Assistant Commissioner of Police within 5 days.
3. Protective measures ordered: phone tapping protection, armed security, or in-camera testimony.
4. In extreme cases, witness relocation and new identity assistance is granted.', 'Witness statement copy, Threat proof (recordings, call logs, threatening letters), FIR copy.', 'Standing Committee / District & Sessions Judge / Police Commissioner', 'District Witness Protection Cell', '1. Application to District Judge. 2. Threat analysis in 5 days. 3. Protection order passed. 4. Armed security or identity concealment enforced.', 'https://www.mha.gov.in', 'Ministry of Home Affairs, Govt. of India', CURRENT_DATE, CURRENT_DATE, 1, 'VERIFIED', 'PUBLISHED', 0)
